window.PACK={"book":{"id":"diwan-buhturi","title":"ديوان البحتري","type":"diwan","author":"البحتري (ت ٢٨٤هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"f8ab5c66e1d4"},"items":[{"id":"diwan-buhturi:1","bookId":"diwan-buhturi","type":"poem","seq":1,"chapter":"البحر: وافر تام","title":"ألان علمت أن البعث حق ،","page":"","text":"ألان علمت أن البعث حق ، … وأن الله يفعل ما يشاء\nرأيت الخثعمي يقل أنفا ، … يضيق بعرضه البلد الفضاء\nسما صعدا ، فقصر كل سام … لهيبته ، وغص به الهواء\nهو الجبل الذي لولا ذراه ، … إذا وقعت على الأرض السماء"},{"id":"diwan-buhturi:2","bookId":"diwan-buhturi","type":"poem","seq":2,"chapter":"البحر: كامل تام","title":"زعم الغراب منبىء الأنباء ،","page":"","text":"زعم الغراب منبىء الأنباء ، … أن الأحبة آذنوا بتناء\nفاثلج ببرد الدمع صدرا واغرا ، … وجوانحا مسجورة الرمضاء\nتأمرني بالعزاء ، وقد ترى … أثر الخليط ، فلات حين عزاء\nصر الفراق عن السلو عزيمتي ، … وأطال في تلك الرسوم بكائي\nزدني اشتياقا بالمدام ، وغنني ، … أعزز علي بفرقة القرناء\nفلعلني ألقى الردى ، فيريحني ، … عما قليل ، من جوى البرحاء\nأخذت ظهور الصالحية زينة … عجبا من الصفراء والحمراء\nنسج الربيع لربعها ديباجة ، … من جوهر الأنوار بالأنواء\nبكت السماء بها رذاذ دموعها ، … فغدت تبسم عن نجوم سماء\nفي حلة خضراء نمنم وشيها … حوك الربيع ، وحلية صفراء\nفاشرب على زهر الرياض يشوبه … زهر الخدود ، وزهرة الصهباء\nمن قهوة تنسي الهموم وتبعث ال … شوق الذي قد ضل في الأحشاء\nيخفي الزجاجة لونها ، فكأنها … في الكف قائمة بغير إناء\nولها نسيم كالرياض ، تنفست … في أوجه الأرواح ، والأنداء\nوفواقع مثل الدموع ، ترددت … في صحن خد الكاعب الحسناء\nيسقيكها رشأ يكاد يردها … سكرى بفترة مقلة حوراء\nيسعى بها ، وبمثلها من طرفه ، … عودا وإبداء على الندماء\nما للجزيرة والشآم تبدلا ، … بعد ابن يوسف ، ظلمة بيضاء\nجف الفرات ، وكان بحرا زاخرا ، … واسود وجه الرقة البيضاء\nولقد ترى بأبي سعيد مرة … ملقى الرحال ، وموسم الشعراء\nإذ قيظها مثل الربيع ، وليلها … مثل النهار ، يخال رأد ضحاء\nرحل الأمير محمد ، فترحلت … عنا غضارة هذه النعماء\n … أيامهن تنقل الأفياء\nإن الأمير محمدا لمهذب ال … إفعال في السراء والضراء\nملك ، إذا غشي السيوف بوجهه ، … غشي الحمام بأنفس الأعداء\nقسمت يداه ببأسه وسماحه … في الناس ، قسمي شدة ورخاء\nملئت قلوب العالمين بفعله ال … محمود من خوف له ورجاء\nأغنى جماعة طيء عما ابتنت … آباؤها القدماء للأبناء\nفإذا هم افتخروا به لم ينجحوا … بقديم ما ورثوا من العلياء\nصعدوا جبالا من علاك ، كأنها … هضبات قدس ، ويذبل ، وحراء\nواستمطروا في المحل منك خلائقا ، … أصفى وأعذب من زلال الماء\nوضمنت ثار محمد لهم على … كلب العدى ، وتخاذل الأحياء\nما انفك سيفك غاديا ، أو رائحا … في حصد هامات ، وسفك دماء\nحتى كفيتهم الذي استكفوك من … أمر العدى ، ووفيت أي وفاء\nما زلت تقرع باب بابك بالقنا ، … وتزوره في غارة شعواء\nحتى أخذت بنصل سيفك عنوة ، … منه الذي أعيا على الأمراء\nأخليت منه البذ ، وهي قراره ، … ونصبته علما بسامراء\nلم يبق فيه خوف بأسك مطمعا … للطير في عود ، ولا إبداء\nفتراه مطردا على أعواده ، … مثل اطراد كواكب الجوزاء\nمستشرفا للشمس ، منتصبا لها ، … في أخريات الجذع كالحرباء\nووصلت أرض الروم وصل كثير … أطلال عزة ، في لوى تيماء\nفي كل يوم قد نتجت منية … لحماتها ، من حربك العشراء\nسهلت منها وعر كل حزونة ، … وملأت منها عرض كل فضاء\nبالخيل تحمل كل أشعث دراع ، … وتواصل الإدلاج بالإسراء\nوعصائب يتهافتون ، إذا ارتمى … بهم الوغى في غمرة الهيجاء\nوالدهر ذو دول ، تنقل في الورى … لفته ظلمة ليلة ليلاء\nيمشون في زغف ، كأن متونها ، … في كل معركة ، متون نهاء\nبيض تسيل ، على الكماة ، فضولها … سيل السراب بقفرة بيداء\nفإذا الأسنة خالطتها خلتها … فيها خيال كواكب في ماء\nأبناء موت يطرحون نفوسهم … تحت المناي ، كل يوم لقاء\nفي عارض يدق الردى ، ألهبته … بصواعق العزمات والآراء\nشلى على منويل أطراف القنا ، … فنجا عتيق عتيقة جرداء\nلو أنه أبطا لهن ، هنية ، … لصدرن عنه ، وهن غير ظماء\nلئن تبقاد القضاء لوقته ، … فلقد عممت جنوده بفناء\nثكلته أشياعه ، وتركته … للموت مرتقبا صباح مساء\nحتى لو ارتشف الحديد ، أذابه … بالوقد من أنفاسه الصعداء"},{"id":"diwan-buhturi:3","bookId":"diwan-buhturi","type":"poem","seq":3,"chapter":"البحر: خفيف تام","title":"يا سعيد ، والأمر فيك عجيب ،","page":"","text":"يا سعيد ، والأمر فيك عجيب ، … أين ذاك التأهيل والترحيب\nنضبت بيننا البشاشة والود … وغارا كما يغور القليب\nزرت رفها فأخلق الوصل بالوص … ل كما يخلق الرداء القشيب\nلا تغرنك حولة الدهر إن ال … دهر ، إن كان مذنبا ، سيتوب\nوتعجب من غير ما أنا فيه ، … فكذا كان مسلم وحبيب\nحفظ الله أحمد بن منيع ، … ما سرى كوكب ، وهبت جنوب\nكان خل الأديب حقا وهل يع … رف حق الأديب إلا الأديب\nلين قلقل ، له خلق عذ … ب ، ووجه طلق ، وصدر رحيب\nما نصيبين لي بدار ، وما لي … من نصيبين غير عرضي نصيب\nفتجمل لنا قليلا كما كن … ت ، فإن الرحيل عنك قريب"},{"id":"diwan-buhturi:4","bookId":"diwan-buhturi","type":"poem","seq":4,"chapter":"البحر: طويل","title":"أجدك ما ينفك يسري لزينبا","page":"","text":"أجدك ما ينفك يسري لزينبا … خيال ، إذا آب الظلام تأوبا\nسرى من أعالي الشام يجلبه الكرى ، … هبوب نسيم الروض تجلبه الصبا\nوما زارني ، إلا ولهت صبابة … إليه ، وإلا قلت : أهلا ومرحبا\nوليلتنا بالجزع بات مساعفا ، … يريني أناة الخطو ، ناعمة الصبا\nأضرت بضوء البدر ، والبدر طالع ، … وقامت مقام البدر لما تغيبا\nولو كان حقا ما أتته لأطفأت … غليلا ، ولافتكت أسيرا معذبا\nعلمتك إن منيت منيت موعدا … جهاما ، وإن أبرقت أبرقت خلبا\nوكنت أرى أن الصدود الذي مضى … دلال ، فما إن كان إلا تجنبا\nفوا أسفي حتام أسأل مانعا ، … وآمن خوانا ، وأعتب مذنبا\nسأثني فؤادي عنك ، أو أتبع الهوى … إليك ، إن استعصى فؤادي أو أبى\nأقول لركب معتفين : تدرعوا … على عجل قطعا من الليل غيهبا\nردوا نائل الفتح بن خاقان إنه … أعم ندى فيكم ، وأقرب مطلبا\nهو العارض الثجاج ، أخضل جوده ، … وطارت حواشي برقه فتلهبا\nإذا ما تلظى في وغى أصعق العدى ، … وإن خاض في أكرومة غمر الربى\nرزين ، إذا ما القوم خفت حلومهم ، … وقور ، إذا ما حادث الدهر أجلبا\nحياتك أن يلقاك بالجود راضيا ، … وموتك أن يلقاك بالبأس مغضبا\nحرون ، إذا عازرته في ملمة ، … فإن جئته من جانب الذل أصحبا\nفتى لم يضيع وجه حزم ، ولم يبت … يلاحظ أعجاز الأمور تعقبا\nإذا هم لم يقعد به العجز مقعدا ، … وإن كف لم يذهب به الخرق مذهبا\nأعير مودات الصدور ، وأعطيت … يداه على الأعداء نصرا مرهبا\nوقيناك صرف الدهر بالأنفس التي … تبجل ، لا نالوك أما ولا أبا\nفلم تخل من فضل يبلغك التي … تحب ، ومن رأي يريك المغيبا\nوما نقم الحساد إلا أصالة … لديك ، وفعلا أريحيا مهذبا\nوقد جربوا بالأمس منك عزيمة … فضلت بها السيف الحسام ، المجربا\nغداة لقيت الليث ، والليث مخدر … يحدد نابا للقاء ومخلبا\nيحصنه من نهر نيزك معقل … منيع ، تسامى روضه وتأشبا\nمرود مغارا بالظواهر مكثبا ، … ويحتل روضا بالأباطح معشبا\nيلاعب فيه أقحوانا مفضضا ، … يبص ، وحوذانا على الماء مذهبا\nإذا شاء غادى عانة ، أو غدا على … عقائل سرب ، إن تنقص ربربا\nيجر إلى أشباله كل شارق ، … عبيطا مدمى ، أو رميلا مخضبا\nومن يبغ ظلما في حريمك ينصرف … إلى تلف ، أو يثن خزيان ، أخيبا\nشهدت لقد أنصفته يوم تنبري … له مصلتا عضبا من البيض ، مقضبا\nفلم أر ضرغامين أصدق منكما … عراكا إذا الهيابة النكس كذبا\nهزبر مشى يبغي هزبرا ، وأغلب … من القوم يغشى باسل الوجه أغلبا\nأذل بشغب ثم هالته صولة ، … رآك لها أمضى جنانا ، وأشغبا\nفأحجم لما لم يجد فيك مطعما ، … وأقدم لما لم يجد عنك مهربا\nفلم يغنه أن كر نحوك مقبلا ، … ولم ينجه أن حاد عنك منكبا\nحملت عليه السيف لا عزمك انثنى ، … ولا يدك ارتدت ، ولا حده نبا\nوكنت متى تجمع يمنيك تهتك ال … ضريبة ، أو لا تبق للسيف مضربا\nألنت لي الأيام من بعد قسوة ، … وعاتبت لي دهري المسيء فأعتبا\nوألبستني النعمى التي غيرت أخي … علي ، فأمسى نازح الدار ، أجنبا\nفلا فزت من مر الليالي براحة ، … إذا أنا لم أصبح بشكرك متعبا\nعلى أن أفواف القوافي ضوامن … لشكرك ما أبدى دجى الليل كوكبا\nثناء تقصى الأرض نجدا وغائرا ، … وسارت به الركبان شرقا ومغربا"},{"id":"diwan-buhturi:5","bookId":"diwan-buhturi","type":"poem","seq":5,"chapter":"البحر: كامل تام","title":"إما ألم ، فبعد فرط تجنب ،","page":"","text":"إما ألم ، فبعد فرط تجنب ، … أو آبه هم ، فمن متأوب\nهجر المنازل برهة حتى انبرت … تثني عزيمته منازل زينب\nوهو الخلي ، وإن أعير صبابة … حتى يطالع مشرقا من مغرب\nإن الفراق جلا لنا عن غادة … بيضاء ، تجلو عن شتيت أشنب\nألوت بموعدها القديم ، وآيست … منه بلي بنانة لم تخضب\nوأرت عهود الغانيات صبابتي … آلا جرى ووميض برق خلب\nفعلام فيض مدامع تدق الجوى ، … وعذاب قلب بالحسان معذب\nوسهاد عين ما يزال يروقها … أجياد سرب ، أو نواظر ربرب\nجزت البخيل وقد عثرت بمنعه … صفحا وقلت رمية لم تكثب\nوعذرت سيفي في نبو غراره ، … أنى ضربت فلم أقع بالمضرب\nوأحب آفاق البلاد ، إلى الفتى ، … أرض ينال بها كريم المطلب\nكم مشرقي قد نقلت نواله ، … فجعلته لي عدة بالمغرب\nولدى بني يزدان حيث لقيتهم … كرم كغادية السحاب الصيب\nفإذا لقيتهم فموكب أنجم … زهر ، وعبد الله بدر الموكب\nقاسي الضمير على التلاد ، كأنما … يغدو على تفريق مال مذنب\nحاط الخلافة ناصحا ومدبرا ، … بوفاء مجتهد ، وعزم مجرب\nولو أنهم ندبوه للأخرى ، إذا … دفع اللواء إلى الشجاع المحرب\nأفديك من عتب الصديق ، وإنه … لأشد من كيد العدو المجلب\nلاقيت جودك بالسماع ، ودوننا … شغل المهاري من فضاء سبسب\nورأيت بشرك والتنايف دونه ، … والليل يكشف غيهبا عن غيهب\nوتبسماتك للعطاء ، كأنها … زهر الربيع خلال روض معشب\nهل أنت مبلغني التي أغدو لها … بمقلص السربال أحمر مذهب\nلو يوقد المصباح منه لسامحت … بضيائه شية كزهر الكوكب\nإما أغر تشق غرته الدجى ، … أو أرثم كالضاحك المستغرب\nمتقارب الأقطار ، يملأ حسنه … لحظات عين الناظر المتعجب\nوأجل سيبك أن تكون قناعتي … منه بأشقر ساطع ، أو أشهب\nوإذا التقى شعري وجودك يسرا ال … نيل الجزيل ، وثنيا بالمركب"},{"id":"diwan-buhturi:6","bookId":"diwan-buhturi","type":"poem","seq":6,"chapter":"البحر: كامل تام","title":"كم بالكثيب من اعتراض كثيب","page":"","text":"كم بالكثيب من اعتراض كثيب … وقوام غصن ، في الثياب ، رطيب\nوبذي الأراكة من مصيف لابس … نسج الرياح ، ومربع مهضوب\nدمن لزينب ، قبل تشريد النوى … من ذي الأراك بزينب ، ولعوب\nتأبى المنازل أن تجيب ، ومن جوى … يوم الديار دعوت غير مجيب\nهل تبلغنهم السلام دجنة ، … وطفاء ، سارية بريح جنوب\nأو تدنينهم نوازع في البرى ، … عجل كواردة القطا المسروب\nفسقى الغضا والنازليه ، وإن هم … شبوه بين جوانح ، وقلوب\nوقصار أيام به شرقت لنا … حسناتها من كاشح ، ورقيب\nكانت فنون بطالة ، فتقطعت … عن هجر غانية ، ووخط مشيب\nإما دنوت من السلو مرويا … فيه ، وبعت من الشباب نصيبي\nفلربما لبيت داعية الصبى ، … وعصيت من عذل ، ومن تأنيب\nيعشى عن المجد الغبي ، ولن ترى … في سؤدد أربا لغير أريب\nوالأرض تخرج في الوهاد ، وفي الربى ، … عمم النبات ، وجل ذلك يوبي\nوإذا أبو الفضل استعار سجية … للمكرمات ، فمن أبي يعقوب\nلا يحتذي خلق القصي ، ولا يرى … متشبها ، في سؤدد ، بغريب\nتمضي صريمته ، وتوقد رأيه ، … عزمات جوذرز وسورة بيب\nشرف تتابع كابرا عن كابر ، … كالرمح أنبوبا على أنبوب\nوأرى النجابة لا يكون تمامها … لنجيب قوم ، ليس بابن نجيب\nقمر من الفتيان ، أبيض صادع … لدجى الزمان الفاحم الغربيب\nأغنى خطوب الدهر ، حتى كفها ، … والدهر سلك حوادث وخطوب\nوإذا اجتداه المجتدون ، فإنه … يهب العلى ، في نيله الموهوب\nكرمت خلائقه ، فصرن قبائلا … لقبائل من رفده ، وشعوب\nكم حزن من ذكر لغفل خامل ، … وبنين من حسب لغير حسيب\nدان على أيدي العفاة ، وشاسع … عن كل ند في الندى ، وضريب\nكالبدر أفرط في العلو ، وضوءه … للعصبة السارين جد قريب\nيهني بني نيبخت أن جيادهم … سبقت إلى أمد العلى المطلوب\nإن قيل : ربعي الفخار ، فإنهم … مطروا بأول ذلك الشؤبوب\nأو تجتبى أقلامهم لكتابة ، … فلقبل ما كانت رماح حروب"},{"id":"diwan-buhturi:7","bookId":"diwan-buhturi","type":"poem","seq":7,"chapter":"البحر: متقارب تام","title":"أبا حسن إن حسن العزا","page":"","text":"أبا حسن إن حسن العزا … ء عند المصيبات والنائبات\nيضاعف فيه الإله الثوا … ب للصابرين والصابرات\nومنزلة الصبر عند البلا … ء كمنزلة الشكر عند الهبات\nومن نعم الله لا شك فيه … حياة البنين وموت البنات\nلقول النبي عليه السلام : … موت البنات من المكرمات"},{"id":"diwan-buhturi:8","bookId":"diwan-buhturi","type":"poem","seq":8,"chapter":"البحر: كامل تام","title":"أحبب إلي بطيف سعدى الآتي ،","page":"","text":"أحبب إلي بطيف سعدى الآتي ، … وطروقهش في أعجب الأوقات\nأنى اهتديت لمحرمين تصوبوا … لسفوح مكة من ربى عرفات\nذكرتنا عهد الشآم ، وعيشنا … بين القباب البيض ، والهضبات\nإذ أنت شكل موافق ومخالف ، … والدهر فيك ممانع ومؤات\nلولا مكاثرة الخطوب ونحتها … من جانبي ، لكنت من حاجاتي\nتلك المنازل ما تمتع واقفا … بزها الشخوص ، ولا وغى الأصوات\nأبني عبيد ، شد ما احترقت لكم … كبدي ، وفاضت فيكم عبراتي\nألقى مكارمكم شجى لي بعدكم ، … وأرى سوابق مجدكم حسراتي\nشرف تفاقد وارثوه ، فأصبحوا … أصداء قفر بالعراء فلاة\nمن بعد ما بنيت على جبل العلى … أحسابهم ، وجروا إلى الغايات\nكانوا هم ثبج الجميع لطيء … في أمرها ، وطوائف الأشتات\nلن تحدث الأيام لي بدلا بهم ، … أيهات من بدل بهم أيهات \\ \\\nومعيري بالدهر يعلم ، في غد ، … أن الحصاد وراء كل نبات\nأبني ! إني قد نضوت بطالتي ، … فتحسرت ، وصحوت من سكراتي\nنظرت إلي الأربعون ، فأصرخت … شيبي ، وهزت للحنو قناتي\nومن الأقارب من يسر بميتتي … سفها ، وعز حياتهم بحياتي\nإن أبق ، أو أهلك ، فقد نلت التي … ملأت صدور أقاربي ، وعداتي\nغنيت ندمان الخلائف نابها … ذكري ، وناعمة بهم نشواتي\nوشفعت في الأمر الجليل إليهم ، … بعد الجليل ، فأنجحوا طلباتي\nوصنعت في العرب الصنائع عندهم ، … من رفد طلاب ، وفك عناة\nفالآن إذ ناصيت أعنان العلى ، … ورقيت منها أرفع الدرجات\nيجري ليدخل في غبار تسرعي … من ليس يعشر في الرهان أناتي\nويذيمني من لو ضغمت قبيله ، … يوم الفخار لطار في لهواتي\nجدي الذي رفع الأذان بمنبج ، … وأقام فيها قبلة الصلوات\nوأبي أبو حيان قائد طيء … للروم ، تحت لوائه المنصات\nوولي فتح الجسر ، إذ أغري به … عمرو ، وفاعل تلكم الفعلات\nوخؤولتي ، فالحوفزان ، وحاتم ، … والخالدان الرافدان حماتي\nإذ لم يكن شرف المناسب يشترى … بالمال في اللأواء واللزبات"},{"id":"diwan-buhturi:9","bookId":"diwan-buhturi","type":"poem","seq":9,"chapter":"البحر: متقارب تام","title":"تظن شجوني لم تعتلج ،","page":"","text":"تظن شجوني لم تعتلج ، … وقد خلج البين من قد خلج\nأشارت بعينين مكحولتين … من الغنج ، إذ ودعت ، والدعج\nعناق وداع ، أجال اعترا … ض دمعي في دمها ، فامتزج\nفهل وصل ساعتنا منشيء … صدود شهور خلت ، أو حجج\nوما كان صدك إلا الدلا … ل ، وإلا الملال ، وإلا الغنج\nفإن تك قد دخلت بيننا … مهامه للآل فيها لجج\nفكم روضة بفناء الربيع … يلامعها البرق من كل فج\nتأيا قويق لتدويرها ، … فنكب عن قصدها وانعرج\nإذا هزت الريح خافورها ، … تعانق نوارها وازدوج\nلقيناك فيها ، فخايلتها … بلين التكفي ، وطيب الأرج\nسقى حلبا حلب مسبل ، … من الغيث يهمي بها ، أو يشج\nوإن حال من دون حقي فلم … يسلمه يعقوبها ابن الفرج\nأيتلف يعقوب مالي لدي … ه ، ويعقوب متئد لم يهج\nوإني مليء بأن لا يسر … بما نال مني ولا يبتهج\nإذا شد عروة زناره … على سلحة ضخمة وانتفج\nتوهم أني لا أستطيع … مساءة أغثر بادي الهوج\nومن أين يكثر أنصاره ، … فيأتي الأحج له ، فالأحج\nفهلا تورع عما جنى … \nأبا يوسف سمج ما أتيت ، … ولم يك مثلك يأتي السمج\nوشرث المسيئين ذو نبوة ، … إذا ليم فيها تمادى ، ولج\nهلم إلى الحق نسري إليه … بحجتنا فيه ، أو ندلج\nونعتمد الصدق حتى يضيء … لنا مظلم الأمر ، أو ينبلج\nوفي موقف ما لنا بعده … تنازع نجوى ، ولا معتلج\nفمن أبرأ الحكم فيه نجا ، … ومن ألحج الحكم فيه لحج"},{"id":"diwan-buhturi:10","bookId":"diwan-buhturi","type":"poem","seq":10,"chapter":"البحر: طويل","title":"سفاها تمادى لومها ولجاجها ،","page":"","text":"سفاها تمادى لومها ولجاجها ، … وإكثارها مما رأت ، وضجاجها\nونبوتها ، إن عاد كفي عيدها ، … وإن هاج نفسي للسماح هياجها\nهل الدهر إلا غمرة وانجلاؤها ، … وشيكا ، وإلا ضيقة وانفراجها\nتقضى الهموم لم يلبث طروقها … زماعي ، ولم يغلق علي رتاجها\nوإني لأمضي العزم ، حتى أرده … إلى حيث لا يلوي الشكوك خلاجها\nإلى ليلة ، إما سراها مبلغي … أجاود إخواني ، وإما ادلاجها\nوما زالت العيس المراسيل تنبري ، … فتقضى لدى آل المدبر حاجها\nأناس ، قديم المكرمات وحدثها … لهم ، وسرير العجم فيهم وتاجها\nإذا خيموا في الدار ضاقت رباعها ، … وإن ركبوا في الأرض ثار عجاجها\nمليون أن تسقى البلاد غياثها … بأوجههم حتى تسيل فجاجها\nكأن ، على بغداد ، ظل غمامة … بجود أبي إسحاق يهمي انثجاجها\nتربعتها ، فازداد ظاهر حسنها ، … وأضعف في لحظ العيون ابتهاجها\nفلا أمل إلا عليك طريقه ، … ولا رفقة إلا إليك معاجها\nيد لك عندي قد أبر ضياؤها … على الشمس حتى كاد يخبو سراجها\nهي الراح تمت في صفاء ورقة ، … فلم يبق للمصبوح إلا مزاجها\nفإن تلحق النعمى بنعمى ، فإنه … يزين اللآلي ، في النظام ، ازدواجها\nوكنت إذا مارست عندك حاجة ، … على نكد الأيام ، هان علاجها\nولم لا أغالي بالضياع ، وقد دنا … علي مداها ، واستقام اعوجاجها\nإذا كان لي ترييعها واغتلالها ، … وكان عليك كل عام خراجها"},{"id":"diwan-buhturi:11","bookId":"diwan-buhturi","type":"poem","seq":11,"chapter":"البحر: طويل","title":"دع الأمر لا تطلبه من نحو وجهه","page":"","text":"دع الأمر لا تطلبه من نحو وجهه … بظنك وارج الأمر من حيث لا يرجى\nإذا الأمر لم يردد عليك اعتلاقه … مزية نفع ، كان تركانه أحجى\nويكدي من الحاجات أقربها مدى … على ظن باغيها ، وأوضحها نهجا\nوما جهل ابن الجرجرائي واجبي … عليه ، ولكن كان ألأمهم علجا\nوأثقل من أهجو علي مغمر ، … أظل بإسفافي إلى هجوه أهجى"},{"id":"diwan-buhturi:12","bookId":"diwan-buhturi","type":"poem","seq":12,"chapter":"البحر: بسيط تام","title":"كنت إلى وصل سعدى جد محتاج ،","page":"","text":"كنت إلى وصل سعدى جد محتاج ، … لو أنه كثب للآمل الراجي\nتدامج الوعد لا نجح ولا خلف ، … مجدولة بين إرهاف ، وإدماج\nشمس أضاعت أمام الشمس إذ برزت … تسير في ظعن منهم ، وأحداج\nمن لابسات حصى الياقوت أوشحة ، … ولم يذلن بلبس الذبل والعاج\nأسقى ديارك ، والسقيا يقل لها ، … إغزار كل ملث الودق ثجاج\nيلقي على الأرض من حلي ، ومن حلل ، … ما يمتع العين من حسن وإبهاج\nفصاغ ما صاغ من تبر ، ومن ورق … وحاك ما حاك من وشيء وديباج\nإلى علي بني الفياض بلغني … سراي من حيث لا يسرى ، وإدلاجي\nإلى فتى ، يتبع النعمى نظائرها ، … ك\nيعود من رأيه ، في كل مشكلة ، … إلى سراج ، يرينا الغيب ، وهاج\nلم أر يوما كيوم قيض فيه لإس … حاق بن أيوب إسحاق بن كنداج\nأخلى لهام عليها بيضها ، وطلى … منه ، وأفرى لأوراد وأوداج\nلما تضايق بالزحفين قطرهما ، … فضارب بغرار السيف ، أو واجي\nقالت له النفس ، لا تألوه ما نصحت ، … والخيل تخلط من نقع ، وإرهاج\nإن المقيم قتيل لا رجوع به … إلى الحياة ، وإن الهارب الناجي\nفمر يهوي هوي الريح يسعده … جو بسيط ، وليل مظلم داج\nإلاتنله العوالي ، وهو منجذب ، … فقد كوت صلويه كي إنضاج\nإن الخلافة لا تلقى كتائبها ، … كما لقيت ، بعواد وصناج\nتركت عود كنيز في العجاج فلم … تربع على رمل فيه ، وأهزاج\nتصيح أوتاره ، والخيل تخبطه ، … يطأن حضنيه ، فوجا بعد أفواج\nفإن رجعت إلى حرب ، فأبق على … خلياق ينشى وبم فيه لجلاج\nإذا تخطفه المضراب حرك في … سر القلوب سرورا ، جد مهتاج\nكانت نصيبين خيسا ما ترام ، فقد … ذلت لليث ، على الأعداء ، ولاج\nأبقى ولولا التلافي من بقيته ، … قاظت لهم نسوة من غير أزواج\nووقعة اللحف ، والهيجاء ساعرة … لهيب يوم ، على الأبطال ، أجاج\nأزال خمسين ألفا ، فانثنوا عصبا ، … والطعن يزعج منهم أي إزعاج\nإقدام أبيض تستعلي مناسبه … به إلى ملك البيضاء ، ذي التاج\nتجلى الشكوك إذا اسودت غيابتها … عن كوكب ، لسواد الشك فراج\nإن أنا شبهته بالغيث في مدحي ، … غضضت منه فكنت المادح الهاجي"},{"id":"diwan-buhturi:13","bookId":"diwan-buhturi","type":"poem","seq":13,"chapter":"البحر: بسيط تام","title":"لك الخلائق فينا السهلة السمح ،","page":"","text":"لك الخلائق فينا السهلة السمح ، … والنيل يسلس للراجي ، وينسرح\nوالمكرمات التي بانت معالمها ، … مشهورة ، كنجوم الليل تتضح\nأما العفاة ، فقد حطوا رواحلهم … بحيث تتسع الدنيا وتنفسح\nفداك من لا نداه صوب غادية … نهمي ، ولا صدره في الجود منشرح\nأمطلقي من يدي السيبي أنت ، فقد … كلت لديه ركاب الطالب الطلح\nأرى على بابه صرعى أضر بهم … طول المطال ، فما أجدوا ، ولا نجحوا\nلنا مواقف في أفياء عرصته ، … تهان أخطارنا فيها وتطرح\nنغشاه لا نحن مشتاقون منه إلى … أنس ، ولا هو مسرور بنا فرح\nإذا طلبنا بلين القول غرته ، … ظلنا نعالج قفلا ليس ينفتح\nأعيا علي ، فلا هيابة فرق … يخشى الهجاء ، ولا هش ، فيمتدح\nيريغ كاتبه صلحي لينقصني ، … ولم يكن بيننا شر ، فنصطلح\nوكم أناس ألاموا في متاجرتي ، … وحاولوا الربح في نقصي ، فما ربحوا"},{"id":"diwan-buhturi:14","bookId":"diwan-buhturi","type":"poem","seq":14,"chapter":"البحر: بسيط تام","title":"أطاع عاذله ، في الحب ، إذ نصحا ،","page":"","text":"أطاع عاذله ، في الحب ، إذ نصحا ، … وكان نشوان من سكر الهوى فصحا\nفما يهيجه نوح الحمام ، إذا … ناح الحمام على الأغصان أو صدحا\nولا تفيض على الأظعان عبرته ، … إذا نأين ، ولو جاوزن مطلحا\nوربما استدعت الأطلال عبرته ، … وشاقه البرق من نجد ، إذ لمحا\nما كان شوقي ببدع يوم ذاك ولا … دمعي بأول دمع في الهوى سفحا\nولمة كنت مشغوفا بجدتها ، … فما عفا الشيب لي عنها ولا صفحا\nإذا نسيت هوى ليلى أشاد به … طيف سرى في سواد الليل إذ جنحا\nدنا إلي على بعد ، فأرقني ، … حتى تبلج وجه الصبح فاتضحا\nعجبت منه تخطى القاع من إضم ، … وجاوز الرمل من خبت وما برحا\nها إن سعي ذوي الآمال قد نجحا ، … وإن باب الندى بالفتح قد فتحا\nأغر يحسن منه الفعل مبتدئا … نعمى ، ويحسن فيه القول ممتدحا\nرد المكارم فينا ، بعدما فقدت ، … وقرب الجود منا ، بعدما نزحا\nلا يكفهر ، إذا انحاز الوقار به ، … ولا تطيش نواحيه إذا مزحا\nخفت إلى السؤدد المجفو نهضته ، … ولو يوازن رضوى حلمه رجحا\n … على قدر جرم الفيل تبنى قوائمه"},{"id":"diwan-buhturi:15","bookId":"diwan-buhturi","type":"poem","seq":15,"chapter":"البحر: طويل","title":"أفي مستهلات الدموع السوافح ،","page":"","text":"أفي مستهلات الدموع السوافح ، … إذا جدن ، برء من جوى في الجوانح\nلعمري ، لقد أبقى وصيف بهلكه … عقابيل سقم للنفوس الصحائح\nأسى مبرح ، بز العيون دموعها ، … لمثوى مقيم في الثرى غير بارح\nفيا لك من حزم وعزم طواهما … جديد الردى ، تحت الصفا والصفائح\nإذا جد ناعيه ، توهمت أنه … يكرر ، من أخباره ، قول مازح\nوما كنت أخشى أن يرام مكانه … بشىء سوى لحظ العيون الطوامح\nولو أنه خاف الظلامة لاعتزى … إلى عصب غلب الرقاب ، جحاجح\nفيا لضلال الرأي كيف أراده … أحباؤه بالمعضلات الجوائح\nتغيب أهل الحلم عنه وأحضرت … سفاهة مضعوف ، وتكثير كاشح\nفألا نهاهم ، عن تورد نفسه ، … تقلب غاد في رضاهم ، ورائح\nوألا أعدوا بأسه وانتقامه ، … لكبش العدو المستميت المناطح\nقتيل يعم المسلمين مصابه ، … وإن خص من قرب قريش الأباطح\nتولى بعزم للخلافة ناصر ، … كلوء ، وصدر للخليفة ناصح\nوكان لتقويم الأمور ، إذا التوت … علينا وتدبير الحروب اللواقح\nإذا ما جروا في حلبة الرأي برزت … تجارب معروف له السبق قارح\nسقى عهده ، في كل ممسى ومصبح ، … دراك الغيوم السانحات ، البوارح\nتعز أمير المؤمنين ، فإنها … ملمات أحداث الزمان الفوادح\nلئن علقت مولاك صبحا فبعدما … أقامت على الأقوام حسرى النوائح\nمضى غير مذموم ، وأصبح ذكره … حلي القوافي ، بين راث ومادح\nفلم أر مفقودا له مثل رزئه ، … ولا خلفا من مثله مثل صالح\nوقور تعانيه الأمور ، فتنجلي … غيابتها عن وازن الحلم ، راجح\nرميت به أفق الشآم ، وإنما … رميت بنجم في الدجنة لائح\nإذا اختلفت سبل الرجال وجدته … مقيما على نهج من الحق ، واضح\nسيرضيك هديا في الأمور وسيرة ، … ويكفيك شعب الأبلخ المتجانح"},{"id":"diwan-buhturi:16","bookId":"diwan-buhturi","type":"poem","seq":16,"chapter":"البحر: بسيط تام","title":"بات نديما لي ، حتى الصباح ،","page":"","text":"بات نديما لي ، حتى الصباح ، … أغيد مجدول مكان الوشاح\nكأنما يضحك عن الؤلؤ … منظم ، أو برد أو أقاح\nتحسبه نشوان ، إما رنا ، … للفتر من أجفانه ، وهو صاح\nبت أفديه ، ولا أرعوي … لنهي ناه عنه ، أو لحي لاح\nأمزج كأسي بجنى ريقه ، … وإنما أمزج راحا براح\nيساقط الورد علينا ، وقد … تبلج الصبح ، نسيم الرياح\nأغضيت عن بعض الذي يتقي … من حرج في حبه ، أو جناح\nسحر العيون النجل مستهلك … لبي ، وتوريد الخدود الملاح\nقل لأبي نوح ، شقيق الندى ، … ومعدن الجود ، وحلف السماح\nأعوذ بالرأي الجميل الذي … عودته ، والنائل المستماح\nمن أن تصد الطرف عني ، وأن … أخيب في جدواك بعد النجاح\nإن كان لي ذنب ، فعفو ، وإن … لم يك لي ذنب ، ففيم اطراح\nأبعد أسباب متان القوى … من فرط شكر سائر ، وامتداح\nبخبرن عن قلب قديم الهوى … فيك ، وعن صدر أمين النواح\nأشمت حسادي ، وأخرجتني … من سيبك المغدى علي المراح\nفهل لأنس بان من رجعة ، … أم هل لحال فسدت من صلاح\nإني من صدك في لوعة ، … تغولت لبي ، وهاضت جناح\nلست على سخطك جلد القوى ، … ولا على هجرك شاكي السلاح"},{"id":"diwan-buhturi:17","bookId":"diwan-buhturi","type":"poem","seq":17,"chapter":"البحر: طويل","title":"وما خفت جدي في الصديق يسوءه ،","page":"","text":"وما خفت جدي في الصديق يسوءه ، … ولكن كثيرا ما يخاف مزاحي\nورب مبار للرياح بجوده ، … من الأجودين الغر ، آل رياح\nمتى بعت مختارا رضاه بسخطه ، … تبدلت خسري ، كله ، بفلاحي\nوكم عاتب بالري يثلم عتبه … مضارب سيفي ، أو يهيض جناحي\nوقفت له نفسي على ذل مذنب ، … يكثر من زار عليه ، ولاح\nكأن الرياحيين ، حيث لقيتهم ، … وإن لؤموا أصلا ، قريش بطاح"},{"id":"diwan-buhturi:18","bookId":"diwan-buhturi","type":"poem","seq":18,"chapter":"البحر: بسيط تام","title":"أضحت بمرو الشاهجان منادحي ،","page":"","text":"أضحت بمرو الشاهجان منادحي ، … ولأهل مرو الشاهجان مدائحي\nوصلوا جناحي بالنوال ، وأمنوا ، … من خوف أحداث الزمان ، جوانحي\nكم من يد بيضاء أشكر غبها … منهم ، وفيهم من أخ لي صالح\nفالله جار أبي علي إنه … أنس الصديق ، وغيظ صدر الكاشح\nشيخ الأمانة والديانة موجف … في مذهب أمم وحلم راجح\nذو عروة ، في الأعجمين ، وثيقة ، … وأرومة مرؤومة في واشح\nنفسي فداء خلائق لك حرة ، … وزناد مجد ، في يمينك ، قادح\nإني أقول ، وما قول معرضا ، … في ذكر مكرمة ، بعبثة مازح\nماذا ترى في مدمج عبل الشوى ، … من نسل أعوج كالشهاب اللائح\nعنق كقائمة القليب ، تعطفت … أودا ، ورأس مثل قعو الماتح\nيختال في شية ، يموج ضياؤها ، … موج القتيرعلى الكمي الرامح\nلو يكرع الظمآن فيها ، لم يمل … طرفا إلى عذب الزلال السائح\nأهديته لتروح أبيض ، واضحا … منه على جذلان أبيض ، واضح\nفتكون أول سنة مأثورة ، … أن يقبل الممدوح رفد المادح"},{"id":"diwan-buhturi:19","bookId":"diwan-buhturi","type":"poem","seq":19,"chapter":"البحر: بسيط تام","title":"العيش في ليل داريا ، إذا بردا ،","page":"","text":"العيش في ليل داريا ، إذا بردا ، … والراح نمزجها بالماء من بردى\nقل للإمام ، الذي عمت فواضله … شرقا وغربا فما نحصي لها عددا\nالله ولاك عن علم خلافته ، … والله أعطاك ما لم يعطه أحدا\nوما بعثت عتاق الخيل في بلد ، … إلا تعرفت فيه اليمن والرشدا\nأما دمشق ، فقد أبدت محاسنها ، … وقد وفى لك مطريها بما وعدا\nإذا أردت ملأت العين من بلد ، … مستحسن ، وزمان يشبه البلدا\nيمسي السحاب على أجبالها فرقا ، … ويصبح النبت في صحرائها بددا\nفلست تبصر إلا واكفا خضلا ، … أو يانعا خضرا ، أو طائرا غردا\nكأنما القيظ ولى بعد جيئته ، … أو الربيع دنا من بعد ما بعدا\nيا أكثر الناس إحسانا وأعرضهم … سيبا وأطولهم في المكرمات يدا\nما نسأل الله إلا أن تدوم لك الن … عماء فينا ، وأن تبقى لنا أبد"},{"id":"diwan-buhturi:20","bookId":"diwan-buhturi","type":"poem","seq":20,"chapter":"قصائد","title":"مخلف في الذي وعد ،","page":"","text":"مخلف في الذي وعد ، … سيل وصلا فلم يجد\nوهو بالحسن مستب … د وبالدل منفرد\nيتثنى على قضي … ب ، ويفتر عن برد\nقد تطلبت مخرجا … من هواه ، فلم أجد\nبأبي أنت ليس لي … عنك صبر ، ولا جلد\nضاق صدري بما أج … ن ، وقلبي بما وجد\nوتغضبت ، إن شكو … ت جوى الحب ، والكمد\nواشتكائي هواك ذن … ب ، فإن تعف لا أعد\nقد رحلنا عن العرا … ق وعن قطبها النكد\nحبذا العيش في دمش … ق ، إذا ليلها برد\nحيث يستقبل الزما … ن ، ويستحسن البلد\nسفر جددت لنا ال … لهو ، أيامه الجدد\nعزم الله للخلي … فة فيه على الرشد\nملك تعجز البر … ية عن حل ما عقد\nيا إمام الهدى الذي اح … تاط للدين ، واجتهد\nسر بسعد السعود في … صحبة الواحد الصمد\nوابق في العز والعل … ولنا ، آخر الأبد"},{"id":"diwan-buhturi:21","bookId":"diwan-buhturi","type":"poem","seq":21,"chapter":"البحر: طويل","title":"أجرني من الواشي الذي جار واعتدى ،","page":"","text":"أجرني من الواشي الذي جار واعتدى ، … وغابر حب غار بي ثم أنجدا\nوإلا ، فأسعدني بدمعك ، إنه … يهون ما بي أن أرى لي مسعدا\nسقى الغيث أجزاعا عهدت بجوها … غزالا ، تراعيه الجآذر ، أغيدا\nإذا ما الكرى أهدى إلي خياله ، … شفى قربه التبريح أو نقع الصدى\nإذا انتزعته من يدي انتباهة ، … عددت حبيبا راح مني ، أو غدا\nولم أر مثلينا ، ولا مثل شأننا ، … نعذب أيقاظا وننعم هجدا\nتصعد أنفاسي جوى وتشوقا ، … إذا البرق منح غربي دجلة أصعدا\nوما ذاك إلا لوعة لك زادها … تنائي الديار جدة ، وتوقدا\nفمن غاب ينوي نية عن حبيبه … وهجرا ، فإني غبت عنك لأشهدا\nوما القرب في بعض المواطن للذي … يرى الحزم ، إلا أن يشط ويبعدا\nإلى ابن أمير المؤمنين تناهبت … بنا العيس ديجورا من الليل ، أسودا\nإلى منعم ، لا الجود عنه بعازب … بطيء ، ولا المعروف منه بأنكدا\nرأينا بني الأمجاد في كل معشر ، … فكانوا لعبد الله في الجود أعبدا\nعليه من المعتز بالله بهجة … أضاءت فلو يسري بها الركب لاهتدى\nإذا أعجبتك اليوم منه خليقة … مهذبة ، أعطاك أمثالها غدا\nطلوب لأقصى غاية ، بعد غاية ، … إذا قلت يوما قد تناهى تزيدا\nسررنا بأن أمرته ، ونصبته … لنا علما يأوي إلى ظله الهدى\nوأبهجنا ضرب الدنانير باسمه ، … وتقليده من أمرنا ما تقلدا\nولم لا يرى ثانيك في السلطة التي … خصصت بها ثانيك في الجود والندى\nحقيق بأن يرمى به الجانب الذي … يهم ، وأن يفضى إليه ويعهدا\nومثلك حاط المسلمين بمثله ، … وليا ، ولم يهمل رعيته سدى\nفلو دام شيء آخر الدهر سرنا … غنى عنه موجود ، ودمت مخلدا\nأبن فضله ، أظهر نباهة قدره ، … وأبق له في الناس ذكرا مجددا\nفللسيف مسلولا أشد مهابة ، … وأظهر إفرندا من السيف مغمدا\nبقيت ترجيه ، وعاش مؤملا ، … يراعي اتصالا من حياتك سرمدا\nلقد ساورت خيل المساور عصبة … أفاءت عليه الطعن غضا مجددا\nحموه سهول الأرض من كل جانب ، … فظل شريدا في الجبال ، مطردا\nعلوج ، وأعراب يرجون حائنا ، … أضاع الحجى حتى طغى وتمردا\nيسمونه باسم الخليفة ، بعدما … رعى الضأن فيهم ذا مشيب وأمردا\nفلم لم تزعه الوازعات ، ويجتنب … عداوة منصور اليدين على العدى\nولو شاور الأيام قبل خروجه ، … نهين ابن أم الكلب أن يتوردا\nكأني به ، إما قتيلا مضرجا … بأيدي الموالي ، أو أسيرا مقيدا"},{"id":"diwan-buhturi:22","bookId":"diwan-buhturi","type":"poem","seq":22,"chapter":"البحر: خفيف تام","title":"إنما الغي أن يكون رشيدا ،","page":"","text":"إنما الغي أن يكون رشيدا ، … فانقصا من ملامه ، أو فزيدا\nخلياه وجدة اللهو ، مادا … م رداء الشباب غضا جديدا\nإن أيامه من البيض بيض ، … ما رأين المفارق السود سودا\nأيها الدهر ! حبذا أنت دهرا ، … قف حميدا ، ولاتول حميدا\nكل يوم تزداد حسنا فما تب … عث يوما ، إلا حسبناه عيدا\nإن في السرب ، لو يساعدنا السر … ب ، شموسا يمشين مشيا وثيدا\nيتدافعن بالأكف ويعرض … ن علينا عوارضا وخدودا\nيتبسمن عن شتيت أراه … أقحوانا مفصلا ، أو فريدا\nرحن ، والليل قد أقام رواقا ، … فأقمن الصباح فيه عمودا\nبمهاة مثل المهاة أبت أن … تصل الوصل ، أو تصد الصدودا\nذات حسن لو استزادت من الحس … ن إليه ، لما أصابت مزيدا\nفهي الشمس بهجة ، والقضيب الغض … لينا ، والرئم طرفا وجيدا\nيا ابنة العامري ! كيف يرى قوم … مك عدلا أن تبخلي ، وأجودا\nإن قومي قوم الشريف قديما ، … وحديثا ، أبوة وجدودا\nوإذا ما عددت يحيى ، وعمرا ، … وأبانا ، وعامرا ، والوليدا\nوعبيدا ، ومسهرا ، وجديا ، … وتدولا ، وبحترا ، وعتودا\nلم أدع من مناقب المجد ما يق … نع من هم أن يكون مجيدا\nذهبت طيء بسابقة المج … د على العالمين بأسا وجودا\nمعشر أمسكت حلومهم الأر … ض وكادت من عزهم أن تميدا\nنزلوا كاهل الحجاز ، فأضحى … لهم ساكنوه ، طرا ، عبيدا\nمنزلا قارعوا عليه العمالي … ق ، وعادا في عزها وثمودا\nفإذا قوت وائل وتميم … كان ، إن كان ، حنظلا وهبيدا\nظل ولداننا يغادون نخلا ، … مؤتيا أكله ، وطلحا نضيدا\nبلد ينبت المعالي فما ي … ثغر الطفل فيه حتى يسودا\nوليوث من طيء ، وغيوث … لهم المجد طارفا ، وتليدا\nفإذا المحل جاء جاؤوا سيولا ، … وإذا النقع ثار ثاروا أسودا\nيحسن الذكر عنهم والأحادي … ث إذا حدث الحديد الحديدا\nفي مقام تخر في ضنكه البي … ض على البيض ركعا وسجودا\nمعشر ينجزون بالخير والشر … يد الدهر موعدا ووعيدا\nيفرجون الوغى ، إذا ما أثار ال … ضرب من مصمت الحديد صعيدا\nبوجوه تعشي السيوف ضياء ؛ … وسيوف تعشي الوجوه وقودا"},{"id":"diwan-buhturi:23","bookId":"diwan-buhturi","type":"poem","seq":23,"chapter":"البحر: طويل","title":"عليك سلام ، أيها القمر البدر ،","page":"","text":"عليك سلام ، أيها القمر البدر ، … ولا زال معمورا بأيامك العمر\nوداعا لشهر ، إن من شاسع النوى … على الكبد الحرى ، إذا التهبت ، شهر\nهو اسم فراق طال أو قصر المدى ، … فللصدر منه ما يحر له الصدر\nأنا الظالم المختار فقدك عالما … بفقد اللهى فيه ، وما ظلم الدهر\nملأت يدي فاشتقت ، والشوق عادة … لكل غريب ذل ، عن يده ، الفقر\nوأي فتى يشتاق ، من بعد أرضه ، … إلى أهله ، حتى يكون له وفر\nتلافيتني في ظمأة ، فدفعتني … إلى نائل ، فيه المخاضة والغمر\nويدنو قرار … تباعد حتى ما ينال له قعر\nولولاك ما أسخطت غمى وروضها … ونهر دجيل بالذي رضي الثغر\nولا كان غزو الروم بعض مآربي ، … وهمي ، ولا مما أطالبه الهجر\nلتعلم أن الود يجمعنا على … صفاء التصافي ، قبل يجمعنا عمرو\nوإني متى أعدد مساعيك أعتدد … بها شرفا ، إذ كان فخرك لي فخر\nولم أر مثلي ظل يمدح نفسه ، … ويأخذ أجرا ، إن ذا عجب بهر\nوما اخترت دارا غير دارك من قلى ، … وأين ترى قصدي ومن دوني\nفإن بنت منكم مصبحا حضر الهوى ، … وإن غبت عنكم سائرا شهد الشعر\nسأشكر لا أني أجازيك نعمة … بأخرى ، ولكن كي يقال له شكر\nوأذكر أيامي لديك وحسنها ، … وآخر ما يبقى من الذاهب الذكر"},{"id":"diwan-buhturi:24","bookId":"diwan-buhturi","type":"poem","seq":24,"chapter":"البحر: سريع","title":"يا موعدا منها ترقبته ،","page":"","text":"يا موعدا منها ترقبته ، … والصبح فيما بيننا يسفر\nهمت بنا ، حتى إذا أقبلت … نم عليها المسك والعنبر\nيا مزنة يحتثها بارق ، … وروضة انوارها تزهر\nما أنصف العاذل في حبكم ، … بمثلكم من يبتلى يصبر"},{"id":"diwan-buhturi:25","bookId":"diwan-buhturi","type":"poem","seq":25,"chapter":"البحر: طويل","title":"سرى من خيال المالكية ما سرى ،","page":"","text":"سرى من خيال المالكية ما سرى ، … فتيم ذا القلب المعنى ، وأسهرا\nدنو بأحلام الكرى من بعيدة ، … تسيء بنا فعلا ، وتحسن منظرا\nوما قربت بالطيف إلا لتنتوي ، … ولا وصلت في النوم إلا لتهجرا\nلقد هجرت والهجر منها سجية ، … ولو وصلت كانت على الوصل أقدرا\nتعذر منها الوصل والوصل ممكن ، … وقصر نوال البيض أن يتعذرا\nفلو شاء هذا القلب في أول الصبي ، … لقصرعن بعض الهوى ، أو لأقصرا\nولكن وجدا لم أجد منه موئلا ، … ومورد حب لم أجد عنه مصدرا\nهوى ، كان غضا بيننا متقدما ، … كما صاب وسمي الغمام ، فبكرا\nنظرت ، وضمت جانبي التفاتة ، … وما التفت المشتاق إلا لينظرا\nإلى أرجواني من البرق ، كلما … تنمر علوي السحاب تعصفرا\nيضيء غماما فوق بطياس واضحا … يبص ، وروضا دون بطياس أخضرا\nوقد كان محبوبا إلي لو انه … أضاء غزالا عند بطياس أحورا\nلقد أعطي المعتز بالله نعمة … من الله ، جلت أن تحد وتقدرا\nتلافى به الله الورى من عظيمة ، … أناخت على الإسلام ، حولا وأشهرا\nومن فتنة شعواء غطى ظلامها … على الأفق ، حتى عاد أقتم أكدرا\nأغر من الأملاك ، إما رأيته … رأيت أبا إسحاق ، والقوم جعفرا\nأعين بأسياف الموالي وصبرهم … على الموت ، لما كافحوا الموت أحمرا\nتقدم في حق الإمامة سهمه ، … إذا رد فيها غيره ، فتأخرا\nويصبح معروفا له الفضل دونهم ، … وما يتداعاه الأباعد منكرا\nأقام منار الحق ، حتى اهتدى به ، … وأبصره من لم يكن قط أبصرا\nوعادت على الدنيا عوائد فضله ، … فأقبل منها كل ما كان أدبرا\nبحلم كأن الأرض منه توقرت ، … وجود كأن\nعمرت ، أمير المؤمنين ، مسلما ، … فعمر الندى والجود في أن تعمرا\nوليس يحاط الحمد والمجد والعلى … بأجمعها ، حتى تحاط وتنصرا\nولما توليت الرعية ، محسنا ، … منعت أقاصي سربا أن تنفرا\nجريت ، وكان القطر أدنى مسافة ، … وأضيق باعا من نداك وأقصرا\nنهضت بأعباء الخلافة كافيا ، … وناضلت عنها ، ساريا ومهجرا\nفلم تسع فيها إذ سعيت مثبطا ، … ولم تعرم عنها إذ رميت مقصرا\nوما زلت إن سالمت كنت موفقا … رشيدا ، وإن حاربت كنت مظفرا\nلئن فت غايات الأئمة سابقا ، … وطلت الملوك سائسا ومدبرا\nفلا عجب في أن يغيضوا وتعتلي ، … ولا منكر في أن يقلوا وتكثرا\nوقد ترك العباس عندك وابنه … على فتن مرمى النجم حيث تحيرا\nهما ورثاك ذا الفقار ، وصيرا … إليك القضيب والرداء المحبرا\nوأي سناء لست أهلا لفضله ، … وأولى به من كل حي وأجدرا\nوأنت ابن من أسقى الحجيج على الظما ، … وناشد في المحل السحاب فأمطرا"},{"id":"diwan-buhturi:26","bookId":"diwan-buhturi","type":"poem","seq":26,"chapter":"البحر: سريع","title":"ألحمد لله على ما أرى","page":"","text":"ألحمد لله على ما أرى … من قدر الله الذي يجري\nما كان ذا العالم من عالمي … يوما ، ولا ذا الدهر من دهري\nيعترض الحرمان في مطلبي ، … ويحكم الخزاز في شعري"},{"id":"diwan-buhturi:27","bookId":"diwan-buhturi","type":"poem","seq":27,"chapter":"البحر: طويل","title":"أراني متى أبغ الصبابة أقدر ،","page":"","text":"أراني متى أبغ الصبابة أقدر ، … وإن أطلب الأشجان لا تتعذر\nأعد سني فارحا بمرورها ، … ومأتى المنايا من سني وأشهري\nوما خلت تبكي بعد قيصر خلة ، … لكل محب قيصر مثل قيصري\nنعم في ابن بسطام وزبرج أسوة ، … ووفر على الأيام ، وابن المدبر\nوبرح بي في زبرج أن يومه … تعجل لم يمهل ، ولم يتنظر\nمتاع من الدنيا حظي ، ومن يفت … حظيا من الدنيا فيحزنه يعذر\nأسيت لمولاه على حسن مسمع ، … خليق لشغل السامعين ، ومنظر\nمضىء تظل العين تصبغ خده ، … متى تثن فيه لحظة يتعصفر\nكأن النجوم الزهر أدته خالصا … لزهرة صبح قد تعلت ومشتري\nيشيد بحاجات النفوس ، إذا اعتزى … إلى ابن سريج أو حكى ابن محرر\nلنعم شريك الراح لي لب ذي الحجى … إذا استهلكته بين ناي ومزهر\nومغتال طول الليل حتى يقيمنا … على ساطع من طرة الفجر أحمر\nغرير ، متى تخلط به النفس تبتهج … له ، ومتى يقرن به العيش يقصر\nإذا ما تراءته العيون تحدثت … بكل مسر ، من هواها ، ومضمر\nأعتد إبهامي أشد أصابعي ، … ولم يتحمل خاتمي حمل خنصري\nوعك منونا صار للموت موردا ، … وكان ارتقاب الموت من وعك خيبر\nومن نكد الأيام إيباء حلة ، … عذاة النواحي بين كوثى وصرصر\nفلو كان مات اللوغبردي قبله ، … وأخر في الباقين من لم يؤخر\nإذا لأسغنا الحادثات التي جنت ، … ولم نتبعها بالملام ، فنكثر\nلطيب بالكافور من كان نشره … أطل من الكافور ، لو لم يكفر\nوتدرج في البرد المحبر صورة ، … كتوشية البرد الصنيع المحبر\nقست كبد لم تعتلل لفراقه ، … وقلب إلى ذكراه لم يتفطر\nعليك أبا العباس بالصبر طيعا ، … فإن لم تجده طائعا ، فتصبر\nولا بد أن يهراق دمع ، فإنما … يرجى ارتقاء الدمع بعد التحدر\nإذا أنت لم تنضح جواك بعبرة ، … غلا في التمادي أوقضى في التسعر"},{"id":"diwan-buhturi:28","bookId":"diwan-buhturi","type":"poem","seq":28,"chapter":"البحر: منسرح","title":"يا مستردا قليل نائله ،","page":"","text":"يا مستردا قليل نائله ، … أكل هذا حرصا على العشره\nدونكها إنها مصرفة … عقاربا في البلاد منتشره"},{"id":"diwan-buhturi:29","bookId":"diwan-buhturi","type":"poem","seq":29,"chapter":"قصائد","title":"كم ليلة فيك بت أسهرها ،","page":"","text":"كم ليلة فيك بت أسهرها ، … ولوعة ، من هواك ، أضمرها\nوحرقة ، والدموع تطفئها ، … ثم يعود الجوى ، فيسعرها\nيا علو ! عل الزمان يعقبنا … أيام وصل ، نظل نشكرها\nبيضاء رود الشباب ، قد غمست … في خجل دائبا يعصفرها\nمجدولة ، هزها الصبى ، فشجا … قلبك مسموعها ومنظرها"},{"id":"diwan-buhturi:30","bookId":"diwan-buhturi","type":"poem","seq":30,"chapter":"البحر: متقارب تام","title":"عدمت النغيل ، فما أدمره ،","page":"","text":"عدمت النغيل ، فما أدمره ، … وأولى الصديق بأن يهجره\nإذا قلت قدمه كيسه ، … عناه من النقص ما أخره\nدعانا إلى مجلس فاحش ، … قبيح بذي اللب أن يحضره\nفجاء نبيذ له حامض ، … يشق على الكبد المقفره\nإذا صب مسوده في الزجا … ج ، فكأس النديم به محبره\nتركت مشمس قطربل ، … وجرعتنا دقل الدسكره\nوما لي أطعتك في شربه ، … كأن لم أخبره ، أو لم أره\nوما لي شرهت إلى مثله ، … وما كنت أعرفني بالشره\nوما يعتريني الذي يعتري … بحق السواد من الأبخره\nلذاك عزمت على الإنصرا … ف ، وعقد أوجب الوقت أن نحذره\nفقمنا على عجل والنجو … م مولية قد هوت مدبره\nوكان الجواز على علة ، … فكدنا نبيت في المقطره\nولما انصرفت أطل الخما … ر بحد سماديره المسهره"},{"id":"diwan-buhturi:31","bookId":"diwan-buhturi","type":"poem","seq":31,"chapter":"قصائد","title":"صنت نفسي عما يدنس نفسي ،","page":"","text":"صنت نفسي عما يدنس نفسي ، … وترفعت عن جدا كل جبس\nوتماسكت حيث زعزعني الده … رالتماسا منه لتعسي ، ونكسي\nبلغ من صبابة العيش عندي ، … طففتها الأيام تطفيف بخس\nوبعيد ما بين وارد رفه ، … علل شربه ، ووارد خمس\nوكأن الزمان أصبح محمو … لا هواه مع الأخس الأخس\nواشترائي العراق خطة غبن ، … بعد بيعي الشآم بيعة وكس\nلا تزرني مزاولا لاختباري ، … عند هذي البلوى ، فتنكر مسي\nوقديما عهدتني ذا هنات ، … آبيات ، على الدنيئات ، شمس\nولقد رابني نبو ابن عمي ، … بعد لين من جانبيه ، وأنس\nوإذا ما جفيت كنت حريا … أن أرى غير مصبح حيث أمسي\nحضرت رحلي الهموم فوجه … ت إلى أبيض المدائن عنسي\nأتسلى عن الحظوظ ، وآسى … لمحل من آل ساسان ، درس\nذكرتنيهم الخطوب التوالي ، … ولقد تذكر الخطوب وتنسي\nوهم خافضون في ظل عال ، … مشرف يحسر العيون ويخسي\nمغلق بابه على جبل القبق … ق إلى دارتي خلاط ومكس\nحلل لم تكن كأطلال سعدى … في قفار من البسابس ، ملس\nومساع ، لولا المحاباة مني ، … لم تطقها مسعاة عنس وعبس\nليس يدرى : أصنع إنس لجن … سكنوه أم صنع جن لإنس\nغير أني أراه يشهد أن لم يك … بانيه في الملوك بنكس\nفكأني أرى المراتب والقوم ، … م ، إذا ما بلغت آخر حسي\nوكأن الوفود ضاحين حسرى ، … من وقوف خلف الزحام وخنس\nوكأن القيان ، وسط المقا … صير ، يرجحن بين حو ولعس\nوكأن اللقاء أول من أم … س ، ووشك الفراق أول أمس\nوكأن الذي يريد اتباعا … طامع في لحوقهم صبح خمس\nعمرت للسرور دهرا ، فصارت … للتعزي رباعهم ، والتأسي\nفلها أن أعينها بدموع ، … موقفات على الصبابة ، حبس\nذاك عندي وليست الدار داري ، … باقتراب منها ، ولا الجنس جنسي\nغير نعمى لأهلها عند أهلي ، … غرسوا من ذكائها خير غرس\nأيدوا ملكنا ، وشدوا قواه … بكماة ، تحت السنور ، حمس\nوأعانوا على كتائب أريا … ط بطعن على النحور ، ودعس\nوأراني ، من بعد ، أكلف بالأش … راف طرا من كل سنخ وإس"},{"id":"diwan-buhturi:32","bookId":"diwan-buhturi","type":"poem","seq":32,"chapter":"البحر: خفيف تام","title":"لابس من شبيبة أم ناض ،","page":"","text":"لابس من شبيبة أم ناض ، … ومليح من شيبة أم راض\nوإذا ما امتعضت من ولع الشي … ب برأسي لم يعد ذاك امتعاضي\nليس يرضى عن الزمان مرو … فيه ، إلا عن غفلة أو تغاض\nوالبواقي من الليالي ، وإن خا … لفن شيئا ، فمشبهات المواضي\nناكرت لمتي ، وناكرت منها … لبس سوء الأخلاف والأعواض\nشعرات أقصهن ويرجع … ن رجوع السهام في الأغراض\nوأبت تركي الغديات والآ … صال ، حتى خضبت بالمقراض\nغير نفع إلا التعلل من شخ … ص عدو لم يعده إبغاضي\nورواء المشيب كالبخص في عي … ني فقل فيه في العيون المراض\nطبت نفسا عن الشباب وما سو … د من صبغ برده الفضفاض\nفهل الحادثات ، يا ابن عويف ، … تاركاتي ولبس هذا البياض\nيكثر الحظ في أناس وإن قل … التأسي بكيسهم ، والتراضي\nما قضى الله للجهول بستر ، … يتلافاه ، مثل حتف قاض\nأفرطت لوثة ابن أيوب ، والشا … ئع من أفن رأيه المستفاض\nجامح في العنان لا يسمع الزج … ر ، ولا ينثني إلى الرواض\nزاعم أن طيف بدعة قد أن … دب بالنهس جلده ، والعضاض\nأخيالات خرد ، أم خيالا … ت سباع وحشية في غياض\nأجلبوا تحت غابة من قنا الخط … وزغف من الحديد مفاض\nمدة ثم أقشعوا لانخراق … فاحش من جموعهم وانفضاض\nبعدما استغرقوا النهاية في النز … ع وأفنوا مذخور ما في الوفاض\nغلبتهم آراء أغلب ، فيا … ض العشيات ، من بني الفياض\nسد تدبيره الفضاء عليهم ، … بعد شغب من درئهم واعتراض\nإن تعاطوا تلك المكايد ضلوا … في مسافاتها الطوال ، العراض\nليس من عصبة ، إذا استأنفوا السع … ي سعوا في تسافل ، وانخفاض\nأو توخوا صيانة كانت الأم … وال أولى بها من الأعراض\nما برحنا نرجو علو علي ، … لاجتبار المطلح المنهاض\nوأياد مبيضة ، والأيادي … فضلها أن تكون ذات ابيضاض\nوديون مضمونة من عدات ، … كضمان الأعداد ملء الحياض\nفالتهني بهن قبل التعني … راهن والقضاء قبل التقاضي\nبأبي أنت ، أنت أول من حو … لني من تحشمي ، وانقباضي\nما الندى في سواك غير حديث … من أناس بادوا ، وفعل ماض\nقد تلافى القريض جودك فارتث … لقا ، مشفيا على الإنقراض\nنعم أبدت المصون المغطى … منه ، تحت الخفوت والإغماض\nكالغوادي أظهرن كل جني ، … مستسر في زاهرات الرياض"},{"id":"diwan-buhturi:33","bookId":"diwan-buhturi","type":"poem","seq":33,"chapter":"البحر: خفيف تام","title":"يا أبا جعفر ! غدونا حديثا ،","page":"","text":"يا أبا جعفر ! غدونا حديثا ، … في سواجير منبج ، مستفيضا\nعرضت عذرتي إليك ، وطالت ، … فاغتفر ذنبي الطويل العريضا\nقطع ابن الغلائلي ودادا ، … كان ، من قبل وصله ، مفروضا\nبت أعطى منه غرائب حسن ، … بات عن منعها الوفاء مريضا\nكفلا ناعما ، وكشحا لطيفا ، … وقواما لدنا ، وطرفا غضيضا\nوغناء لمن أراد غناء ، … وقريضا لمن أراد قريضا\nوإذا ما أردت أن تمنع النا … س ورود الفرات كنت بغيضا\nإنما كنت واردا في جميع ال … ناس من كان للورود مفيضا"},{"id":"diwan-buhturi:34","bookId":"diwan-buhturi","type":"poem","seq":34,"chapter":"البحر: رمل تام","title":"شرطي الانصاف ، لو قيل اشترط ،","page":"","text":"شرطي الانصاف ، لو قيل اشترط ، … وخليل من إذا صافى قسط\nأدع الفضل ، فلا أطلبه ، … حسبي العدل من الناس فقط\nوسط الاخوان لا يدخل لي … في حساب ، وأخو الدون الوسط\nوالمعنى من تمنى ، خاليا ، … نقل أخلاقي من بعد الشمط\nأيها الحر الذي شيمته … صحة الرأي ، إذا الرأي اختلط\nشطط أحرج ما كلفتني ، … ومن الجور تكاليف الشطط\nليس لي عتب على حادثة ، … هبني النجم علا ، ثم هبط\nلست بالمرء إذا أسقطته … من عداد في مرجيك ، سقط\nعادة الأيام عندي غضة ، … خلة تصدف ، أو دار تشط"},{"id":"diwan-buhturi:35","bookId":"diwan-buhturi","type":"poem","seq":35,"chapter":"البحر: متقارب تام","title":"أبا نهشل رأيك المقنع ،","page":"","text":"أبا نهشل رأيك المقنع ، … إذا طرق الحادث المفظع\nفماذا اشتهيت من الختلي ، … وهل لك في الثور مستمتع\nتنادمه ، وهو في حالة … تضر الندامى ، ولا تنفع\nوينقل بينكم جعسه ، … إذا كظه القدح المترع\nإذا ما أغار على سلحة … ربوص ، فخنزيرة متبع\nولم يك فيها ابن كلبيها ، … ليصنع بعض الذي يصنع\nفويل لشعر أبي البرق ، إن … أطاف به الأشيب الأنزع\nسيأكله فيريح العبا … د من نتنه ، ثم لا يشبع"},{"id":"diwan-buhturi:36","bookId":"diwan-buhturi","type":"poem","seq":36,"chapter":"البحر: طويل","title":"ترى الليل يقضي عقبة من هزيعه ،","page":"","text":"ترى الليل يقضي عقبة من هزيعه ، … أم الصبح يجلو غرة من صديعه\nأو المنزل العافي يرد أنيسه … بكاء على أطلاله ، وربوعه\nإذا ارتفق المشتاق كان سهاده … أحق بجفني عينه من هجوعه\nولوعك أن الصب إما متمم … على وجده ، أو زائد في ولوعه\nولا تتعجب من تماديه إنها … صبابة قلب مؤيس من نزوعه\nوكنت أرجي في الشباب شفاعة ، … وكيف لباغي حاجة بشفيعه\nمشيب كنث السر عي بحمله … محدثه ، أو ضاق صدر مذيعه\nتلاحق حتى كاد يأتي بطيئه ، … لحث الليالي ، قبل أتي سريعه\nأخذت لهذا الدهر أهبة صرفه ، … ولما أشارك جازعا في هلوعه\nولم تبن دار العجز للملحس الذي … مطيته مشدودة بنسوعه\nوليس امرأ إلا امرؤ ذهبت به … قناعته ، منحازة عن قنوعه\nإذا صنع الصفار سوءا لنفسه ، … فلا تحسد الصفار سوء صنيعه\nوكان اختيال العلج من عطش الردى … إلى نفسه ، شر النفوس ، وجوعه\nعبا لجميع الشر همة مائق ، … وقد كان يكفي بعضه من جميعه\nوردت يديه ، عن مساواة رافع ، … زيادة عالي القدر عنه ، رفيعه\nبصولته كان انقضاض بنائه … لأسفل سفل ، وانفضاض جموعه\nولم ينقلب من بست ، إلا ورأيه … شعاع ، وإلا روعه شغل روعه\nفإن يحي لا يفلح ، وإن يثو لا يكن … لباك عليه موضع لدموعه\nدم إن يرق لا يقض تبلا مراقه ، … ولا يطفىء الأوغام لؤم نجيعه\nشفى برح الأكباد أن ابن طاهر … هوت أم عاصيه بسيف مطيعه\nترجي خراسان جلاء ظلامها … ببدر ، من الغرب ارتقاب طلوعه\nمتى يأتها يعرف مقوم درئها ، … ولا يخف كافي شانها من مضيعه\nمتى قظت في شرق البلاد ، فإنني … زعيم بأن قيظه من ربيعه\nلقد جشم الأعداء ورد نفاسة … عليك ، يلاقون الردى في شروعه\nوكم ظهرت ، بعد استتار مكانها ، … شناة ، خباها كاشح في ضلوعه\nومرضى من الحساد قد كان شفهم … توقع هذا الأمر ، قبل وقوعه\nوما عذرهم في أن تعل صدورهم … على ناشر الإحسان فيهم ، مشيعه\nلئن شهر السلطان أمضى سيوفه ، … ورشح عود الملك أزكى فروعه\nفلا عجب أن يطلب السيل نهجه ، … وأن يستقيم المشتري من رجوعه"},{"id":"diwan-buhturi:37","bookId":"diwan-buhturi","type":"poem","seq":37,"chapter":"البحر: سريع","title":"كلفني ، فوق الذي أستطيع ،","page":"","text":"كلفني ، فوق الذي أستطيع ، … معتزم في لومه ما يريع\nلجاجة منه تأدى بها … إلى الذي ينصبني ، أم ولوع\nيأمر بالسلوان جهلا وقد … شاهد ما بثته تلك الدموع\nومن عناء المرء أو أفنه … في الرأي ، أن يأمر من لا يطيع\nوالظلم أن تلحي على عبرة … مظهرة ما أضمرته الضلوع\nهو المشوق استعزرت دمعه … معاهد الألاف ، وهي الربوع\nطول هذا الليل أن لا كرى … يريك من تهوى وأن لا هجوع\nيمضي هزيع لم يطف طائف … من عند أسماء ، ويأتي هزيع\nإذا توقعنا نواها جرت … سواكب ، يحمر فيها النجيع\nتوقع الكره ازدياد إلى … عذاب من يرقبه لا الوقوع\nألمال مالان ، فرباهما … معط لمن يسأله ، أو منوع\nواليأس فيه العز مستأنفا ، … وفي أكاذيب الرجاء الخضوع\nمن جعل الإسراف يقتاده ، … فقد أراني ما يراه الخليع\nقناعة تتبعها همة ، … مشتبه فيها الغنى والقنوع\nلتطلبن الشاه عيدية ، … تغص من بدن بهن النسوع\nإذا بعثناهن ذدن الكرى … عنا ، إلى حيث أطباه الضجوع\nبالسير مرفوعا إلى سيد ، … مكانه فوق ذويه رفيع\nإضاءة من بشره لا يرى … مثل تلاليها الحسام الصنيع\nوبسطة من دونه ، لو خلا … شبه لها صيغت عليه الدروع\nيدنو ركاباه لمس الحصى ، … والطرف مستعل قراه تليع\nويذعر الأعداء من فارس ، … يهولهم إشرافه ، أو يروع\nأهواؤهم شتى لعرفانه ، … وهم سوى ما أضمروه جميع\nلا تغترر من حلمه ، واحترس … من سطوة فيها الحمام النقيع\nيؤنس بالسيف ، اغترارا به ، … وفي غرار السيف موت ذريع\nثاني وجوه الخيل مقورة … في الكر حتى يستقل الصريع\nإذا شرعنا في ندى كفه ، … ألحقنا بالري ذاك الشروع\nوإن أفضنا في نثاه ، فقل … في نفحات المسك ، غضا ، يضوع\nمشفع في فضل أكرومة … معجلة عن وقتها ، أو شفيع\nنجري إلى أقسامنا عنده ، … فما كث عن حظه ، أو سريع\nوالأنجم الخمسة تجري ، وقد … يريث طورا بعضهن الرجوع\nبالغرش أو بالغور من رهطه ، … أروم مجد ساندتها الفروع\nليس الندى منهم بديعا ، ولا … ما بدأوه من جميل بديع\nلا يرتئي الواجد منهم سوى … ما يرتئيه ، في العلو ، الجميع\nمكارم فضلن من يشتري … نباهة الذكر على من يبيع\nيرجو لها الحساد نقلا ، وقد … أرسى ثبير ، وتأيا تبيع\nركني ، بآلاء أبي غانم ، … ثبت ، وكهفي في ذراه منيع\nكم أدت الأيام لي ذمة … محفوظة ، في ضمنه ، ما تضيع\nوكم لبست الخفض في ظله ، … عمري شباب ، وزماني ربيع"},{"id":"diwan-buhturi:38","bookId":"diwan-buhturi","type":"poem","seq":38,"chapter":"البحر: طويل","title":"ونكثر أن نستودع الله ظاعنا ،","page":"","text":"ونكثر أن نستودع الله ظاعنا ، … يودع صافي العيش ، حين يودع\nبنو مخلد إن يشرع الحمد يشرهوا … إليه ، وإن يدعوا إلى المجد يسرعوا\nإذا نحن شيعنا من القوم واحدا ، … هجرنا الكرى ، حتى يؤوب المشيع"},{"id":"diwan-buhturi:39","bookId":"diwan-buhturi","type":"poem","seq":39,"chapter":"البحر: طويل","title":"أخا علة ، سار الإخاء ، فأوضعا ،","page":"","text":"أخا علة ، سار الإخاء ، فأوضعا ، … وأوشك باقي الود أن يتقطعا\nبدأت وبادي الظلم أظلم ، فانتحى … بك القول شأوا رد منك فأسرعا\nوما أنا بالظمآن فيك إلى التي … أرى ، بين قطريها ، لجنبك مصرعا\nأغار على ما بيننا أن يناله … لسان عدو لم يجد فيك مطمعا\nوآنف للديان أن ترتمي به … غضاب قوافي الشعر خمسا وأربعا\nوكم حفرة في غور نجران أشفقت … ضلوعي ، على أصدائها ، أن تروعا\nملكت عنان الهجر أن يبلغ المدى ، … ونهنهت قول الشعر أن يتسرعا\nفإن تدعني للشر أسرع ، وإن تهب … بصلحي ، فقد أبقيت للصلح موضعا"},{"id":"diwan-buhturi:40","bookId":"diwan-buhturi","type":"poem","seq":40,"chapter":"البحر: طويل","title":"جفانا الكميتي الكبير ولم يكن","page":"","text":"جفانا الكميتي الكبير ولم يكن … لنا في الكميتي الصغير شفيع\nوما متعانا في المقام بأنسة ، … وقد علما أن الفراق سريع\nمتى يصلانا والديار شتيتة … إذا قطعانا والديار جميع"},{"id":"diwan-buhturi:41","bookId":"diwan-buhturi","type":"poem","seq":41,"chapter":"البحر: سريع","title":"لي سيد قد سامني الخسفا ،","page":"","text":"لي سيد قد سامني الخسفا ، … أكدى من المعروف ، أم أصفى\nأستر ما غير من رأيه ، … أريد أن يخفى ، فما يخفى\nداعبني بالمطل ، مستأنيا ، … وعده من فعله ظرفا\nقد كنت من أبعدهم همة … عندي ، ومن أجودهم كفا\nألمائة الدينار منسية ، … في عدة أشبعتها خلفا\nلا صدق إسماعيل فيها ، ولا … وفاء إبراهيم ، إذ وفى\nإنح كنت لا تنوي نجاحا لها ، … فكيف لا تجعلها ألفا\nهل لك في الصلح ، فأعفيك من … نصف ، وتستأنف لي نصفا\nأو نترك الود على حاله ، … وتستوي أقدامنا صفا\nإن الذي يثقل أهل لأن … يضرب عنه للذي خفا"},{"id":"diwan-buhturi:42","bookId":"diwan-buhturi","type":"poem","seq":42,"chapter":"البحر: منسرح","title":"خيال ماوية المطيف ،","page":"","text":"خيال ماوية المطيف ، … أرق عينا لها وكيف\nأكثر لومي على هواها ، … ركب ، على دمنة ، وقوف\nيرتج من خلفها كثيب ، … يعيا به خصرها الضعيف\nوصيفة في النساء رود ، … كأنها خفة وصيف\nأصبح في الحارث بن كعب … طود ، على مذحج ، منيف\nترجى الرغيبات في ذراه ، … ويؤمن الحادث المخوف\nلله عبدون أي فذ ، … تخف عن وزنه الألوف\nترى أجلاء كل قوم ، … وهم على رفده عكوف\nشرفتم ، واعتلى عليكم … بطوله ، ذلك الشريف\nعم بجدواه كل حي ، … فذا تليد ، وذا طريف\nبت ووالي السواد مثلي ، … يجمعنا بره اللطيف\nكان مضيفا ، وكنت ضيفا ، … فاشتبه الضيف والمضيف"},{"id":"diwan-buhturi:43","bookId":"diwan-buhturi","type":"poem","seq":43,"chapter":"البحر: كامل تام","title":"حييت من متربع ومصيف ،","page":"","text":"حييت من متربع ومصيف ، … كانا محلي زينب ، وصدوف\nوكسيتما زهر الربيع وعشبه ، … متألفين بأحسن التأليف\nفلقد عهدتكما ، وفي معناكما … سؤال المحب ، وحاجة المشعوف\nمن كل مرهفة يجيل وشاحها … عطفا قضيب ، في القوام ، قضيف\nتهتز في هيف ، وما بعث الهوى … منهن مثل المرهفات الهيف\nبيض مزجن لي الوصال بهجرة ، … ووصلن لي الإغرام بالتكليف\nإذ لا ينهنهني العذول ولا أرى … متوقفا للوم والتعنيف\nحتام تفرط في الصبابة لوعتي ، … ويفيض ساجم دمعي المذروف\nفلتعزفن عن الصبابة همتي ، … وليقصرن على الديار وقوفي\nولأشكرن أبا علي ، إن من … جدوى يديه تالدي وطريفي\nأعلى مكاني طوله ، وأحلني … في باذخ ، عند الإمام ، منيف\nصنع الصنائع في الرجال ، ولم يكن … كملعن في البحث والتكشيف\nوكفى صروف الدهر مضطلعا بها ، … والدهر ترب حواد وصروف\nفمتى خشيت من الزمان ملمة ، … لاقيتها ، فدفعتها بوصيف\nبالأبيض الوضاح ، حين تنوبه … حاجاتنا ، والأزهر الغطريف\nخرق من الفتيان ، بان مبرزا … بكماله ، وفعاله الموصوف\nملك يضيء من الطلاقة وجهه ، … فتخاله بدر السماء الموفي\nألله جارك حيث كنت ، ممتعا … بمواهب الإعزاز والتشريف\nإني لجأت إلى ذراك مخيما … فيه وعذت بظللك المألوف\nماموضعي بمذمم عندي ، ولا … سيبي وقد أكدته ، بضعيف\nلي حاجة شرفت ، وليس ببالغ … فيها الذي أملت غير شريف\nوقد ابتدأت بمثلها لا مائلا … فيها إلى مطل ، ولا تسويف\nفلئن ثنيت بها ، فليس بمنكر … أن تتبع المعروف بالمعروف"},{"id":"diwan-buhturi:44","bookId":"diwan-buhturi","type":"poem","seq":44,"chapter":"البحر: خفيف تام","title":"حضرموت ، وأين حضرموت ،","page":"","text":"حضرموت ، وأين حضرموت ، … بلد دونه الفلا والفيافي\nأأبي ، يا أخي ، أبوك فتهجو ، … أم أبو خثعميك الإسكافي\nنحن من قد علمت في الشرف الوا … في ، فأجمل في عشرة الأشراف\nسلف لو رأيتهم لتبين … ت لهم زلفة على الأسلاف\nوإذا ما انتقدت شيخك فيهم … طال فيه تصفح الصراف"},{"id":"diwan-buhturi:45","bookId":"diwan-buhturi","type":"poem","seq":45,"chapter":"البحر: طويل","title":"ومهتزة الأعطاف نازحة العطف","page":"","text":"ومهتزة الأعطاف نازحة العطف … منعمة الأطراف ، فاترة الطرف\nتثنى على قد غريب قوامه ، … وتضحك عن مستعذب أفلج الرصف\nإذا بعدت أبلت وإن قربت شفت ، … فهجرانها يبلي ، ولقيانها يشفي\nبذلت لها الود الذي بخلت به ، … وأصفيتها الود الذي لم تكن تصفي\nوأبديت وجداني بها وصبابتي ، … وإن الذي أبدي لدون الذي أخفي\nدنوا فقد تيمت بالبعد والنوى ، … ووصلا فقد عنيت بالصد والصدف\nأما يطمع المحروم عندك في الجدا ، … ولا يطمع المظلوم عندك في النصف\nلعمر أمير المؤمنين لقد عفى … نوائب دهر ، مثله مثلها يكفي\nغدا وهوكهف المسلمين وردوهم ، … فأكرم به من ردء قوم ومن كهف\nكريم السجايا وافر الجود والندى ، … فلا ناقص الجدوعى ولا جامد الكف\nيحن إلى المعروف ، حتى ينيله ، … كما حن إلف مستهام إلى إلف\nويقلق حتى ينجز الوعد مثل ما … يجافي الذي يمشي على رمض الرضف\nوإما أعد نفسي عليك ، رغيبة … من النيل ، أصبح في أمان من الخلف\nوما ألف ألف من جداك كثيرة ، … وكيف أخاف الفوت عندك في ألف"},{"id":"diwan-buhturi:46","bookId":"diwan-buhturi","type":"poem","seq":46,"chapter":"البحر: طويل","title":"أما والذي أعطاك فضلا وبسطة","page":"","text":"أما والذي أعطاك فضلا وبسطة … على كل حي ، واصطفاك على الخلق\nلقد سستنا بالعدل والبذل منعما ، … وعدت علينا بالأناة وبالرفق\nوإنا نرى سيما النبي محمد ، … وسنته في وجهك الضاحك الطلق\nوقد علمت تلك العمامة أنها … تلاث على تلك النجاة والعتق\nتداركت بالإحسان حمصا وأهلها ، … وقد قارفوا فعل الإساءة والخرق\nطلعت لهم وجه الشروق ، فأبصروا … سنا الشمس من أفق ووجهك من أفق\nوما عاينوا شمسين ، قبلهما ، التقى … ضياؤهما يوما ، من الغرب والشرق\nأريتهم إذ ذاك قدرة قاهر ، … وعفو محب للسلامة ، مستبق\nولو شئت طاحوا بالسيوف وبالقنا ، … وباللهذميات المذربة الزرق\nمننت عليهم بالحياة فأصبحوا … مواليك فازوا منك بالمن والعتق\nوإن ولاء المعتقين من الردى ، … يفوق ولاء المعتقين من الرق\nبقيت أمير المؤمنين لأمة ، … سلكت بها نهج السبيل إلى الحق\nبعدلك تستعدي على الدهر ، كلما … أساء ، كما كانت بوجهك تستسقي"},{"id":"diwan-buhturi:47","bookId":"diwan-buhturi","type":"poem","seq":47,"chapter":"البحر: رمل تام","title":"قلت للائم في الجب أفق ،","page":"","text":"قلت للائم في الجب أفق ، … لا تهون طعم شيء لم تذق\nتبهش النفس إلى زور الكرى ، … ومتاع النفس في زور الأرق\nصفوة الدهر إذا الدهر صفا ، … تجمع الشمل ، إذا الشمل افترق\nأغريم الصب أدى دينه ، … ليلة الوعد ، أم الطيف طرق\nلا يلذ الملتقى ، إن لم يكن … باعث الشوق لذيذ المعتنق\nلو أنالت كان ، في تنويلها ، … بلغة الثاوي ، وزاد المنطلق\nنظرت قادرة أن ينكفي … كل قلب ، في هواها ، بعلق\nقال بطلا ، وأفال الرأي من … لم يقل إن المنايا في الحدق\nإن تكن محتسبا من قد ثوى … لحمام فاحتسب من قد عشق\nيملأ الواشي جناني ذعرا ، … ويعنيني الحديث المختلق\nحبها ، أو فرق من هجرها ، … وصريح الذل حب ، أو فرق\nأدع الصاحب لا أعذ له ، … لا يسمى بعقوق ، فيعق\nوأرى الإملاق أحجى بالفتى … من ثراء ، يطبيه بالملق\nليس فيه غير ما يغري به ، … فإذا قيل : انشوى ، قال : احترق\nأكثر الإشفاق يرجى نفعه ، … بعد أن تطرح الخل الشفق\nهبل الجحش ، فما أوتح ما … يقتنيه من قبول ، أو لبق\nوإخاء منه لو يعرض لل … بيع في سوق الثلاثا ما نفق\nوكأن الفسل يأتي ما أتى … من قبيح في رهان ، أو سبق\nمن زيادات النقيصات له … طبق ، يركبه بعد طبق\nكان قبح الوجه يجزينا ، فقد … زادنا ملعوننا قبح الخلق\nعلم في الإفك ، لو قال لنا … كلمة الإخلاص ما خلنا صدق\nغلظ في جرمه يشفعه … حسب ، أهزل في اللؤم ، فدق\nفرخ مجهولات طير ، كلها … قد رعى في مسرح الذم وزق\nنسب في القفص ، أوحاناتها ، … مستعير رقعة من كل زق\nوإذا خالف أصلا فرعه ، … كان حقا لم يوافقه الطبق\nسائخ في الأرض ، لا ترفعه … خصلة يخثر فيها ، أو يرق\nمدبر الخيرات ولى نفعه ، … فتقضى مثل ما ولى الشفق\nهندمت كفاه ، من دون الذي … يبتغى ، هندمة الباب انصفق\nلو طلبنا بلة من رفده ، … وجدت أعمق من بئر العمق\nلم نصادف خلة نحمدها … عنده ، غير هدايات الطرق\nلا تعجب أن ترى خاتمه ، … وعليه الجحش بالله يثق\nلو صفرنا عب في الماء ، ولو … مر مجتازا على الأتن نهق\nإن مشى هملج ، أو صاح إلى … صاحب عشر ، أو مات نفق\nموثق الأسر ، ضليع ، أشرفت … جبهة منه ، ورأس وعنق\nلا وظيف العير مرقوم ولا العجب … مهضوم ، ولا الوجه خلق\nوصحيح لم يقم نخاسه … يتبرامن عشى ، أو من سرق\nأزرق العين ، ومن إبداعه … أن أرى في أعين الحمر زرق\nوإذا أسرى إلى فاحشة ، … أخذ المرفوع ، أو سار العنق\nعده كان أجيرا ، فانقضى … شهره ، أوكان عبدا فأبق\nلو حسبنا ما عليه وله ، … لكفرنا أن حرمنا ورزق\nتخطىء الدنيا المقادير ففي ال … جو من لم يك في قعر النفق\nكان يحيي ميتا ، من ظمإ ، … فضل ما أوبق ميتا من غرق\nبرزت بالمخلديين على ، … كجمام\nلو توفي ما لنا في صاعد ، … لصعدنا من علو ، في الأفق\nقدره مرتفع عن حظه ، … لا يرعك الحظ لم يؤخذ بحق\nيعجل الموعد ، أو يسبقه ، … نائل لو سابق السيف سبق\nهز عطفيه الندى ، مكتسيا … ورق الحمد ، أثيثا يأتلق\nلست أرضى هزة يأتي بها … غصن إن لم يكن غض الورق\nحازم ، يجمع في تدبيره … بدد الملك ، إذا طار شقق\nلملوك في الذرى من مذحج ، … وقعت مبعدة عنها السوق\nيحسب الواحد منهم فئة … جمة ، والعين أثمان الورق\nيتبع النهج الأشط المنتوى ، … في معالي الأمر ، والفعل الأشق\nيتولى ، دون خفاق الحشا ، … صدمة الرايات زورا تختفق\nلا يحب الخرق ، إلا في الوغى ، … إن بذل النفس للموت خرق\nيعمل الهندي ، محمر الظبى … فيه ، والخطي مصفر الخرق\nحصر الأعداء ، في قدرته ، … ظفر ، لو زوال النجم لحق\nيرتجى للصفح موتورا ، ولا … يهب السؤدد فيه للحنق\nمتبع كل مضيق فرجة ، … ممسك من كل نفس برمق"},{"id":"diwan-buhturi:48","bookId":"diwan-buhturi","type":"poem","seq":48,"chapter":"البحر: سريع","title":"أن رق لي قلبك مما ألاق","page":"","text":"أن رق لي قلبك مما ألاق … من فرط تعذيب ، وطول اشتياق\nوجدت بالوصل على مغرم ، … فزوديني منك قبل انطلاق\nإن أنت ودعت بتقبيلة ، … كانت يدا مشكورة للفراق\nأحاذر البين من أجل النوى ، … طورا ، وأهواه من أجل العناق\nقد جعل الله إلى جعفر … حياطة الدين ، وقمع النفاق\nطاعته فرض ، وعصيانه … من أعظم الكفر ، وأعلى الشقاق\nمن لم يبحك النصح من قلبه ، … فما له في دينه من خلاق\nإسلمء لنا يسلم لنا عزنا ، … وابق ، فإن الخيرما عشت باق\nإن دمشقا أصبحت جنة ، … مخضرة الروض ، عذاة البراق\nهواؤها الفضفاض غض الندى ، … وماؤها السلسال عذب المذاق\nوالدهر طلق بين اكنافها … والعيش فيها ذو حواش رقاق\nناظرة نحوك مشتاقة … منك إلى القرب ، ووشك التلاق\nوكيف لا تؤثرها بالهوى ، … وصيفها مثل شتاء العراق"},{"id":"diwan-buhturi:49","bookId":"diwan-buhturi","type":"poem","seq":49,"chapter":"البحر: كامل تام","title":"قربت ، من الفعل الكريم ، يداكا ،","page":"","text":"قربت ، من الفعل الكريم ، يداكا ، … ودنا على المتطلبين مداكا\nفاسلم ، أبا نوح ، لنشييد العلى ، … وفداك من صرف الزمان عداكا\nإني لأضمر للربيع محبة ، … إذا كنت أعتد الربيع أخاكا\nوأراك بالعين التي لم تنصرف … ألحاظها ، إلا إلى نعماكا\nما للمدام تأخرت عن فتية ، … عزموا الصبوح ، وأملوا جدواكا\nبكرت لهم سقيا الربيع ، وقصرت … عنهم ، أوان تلعة ، سقياكا\nما كان صوب المزن يطمع قبلها … في أن يجيء نداه ، قبل نداكا\nولديك صهباء ، كأن نسيمها … من طيب عرفك ، أو جميل ثناكا\nوكأن بشرك في شعاع كؤوسها ، … لما توالت في الأكف دراكا\nتجلو برونقها العيون ، إذا أتت … رسلا ، ونشربها على ذكراكا\nيغني النديم عن الغناء حديثنا … بمحاسن لك ، لم تكن لسواكا"},{"id":"diwan-buhturi:50","bookId":"diwan-buhturi","type":"poem","seq":50,"chapter":"البحر: كامل تام","title":"هل أنت مستمع لمن ناداكا ،","page":"","text":"هل أنت مستمع لمن ناداكا ، … فتهيب عن شوق إليك دراكا\nيا يوسف بن محمد دعوى امرىء ، … عدل الهوى بلسانه ، فدعاكا\nلا يعدم العافون حيث توجهوا ، … يدك الهتون ووجهك الضحاكا\nما زلت مذ جاريت سابق معشر … قصدوا العلى ، حتى رهقت أباكا\nفجرى على غلوائه ، وعلقته … بالجري لا فوتا ، ولا إدراكا\nصرفوك عن حرب الثغور بقدر ما … عرفوك ، يا ابن محمد ، بسواكا\nدحضت به قدماه عن أهوية ، … ثبتت عليها بالهدى قدماكا\nفوراءك الإسلام محروس القوى … لما جعلت أمامك الإشراكا\nوالروم تعلم أن سيفك لم يزل … حتفا لصيد ملوكها ، وهلاكا\nولو احتضنتهم بأيدك لالتقت ، … من خلف أمواج الخليج ، يداكا\nلن يأخذ الحساد مجدك بالمنى ، … الله أعطاك الذي أعطاكا\nأهدى السلام لك السلام ونعمة … تهدي الغليل إلى صدور عداكا\nوحدا الغمام إلى الثغور ركابه ، … حتى أناخ بعلوها ، فسقاكا\nأرض تتيه على السحاب إذا التقى … سيحان في حجراتها ، ونداكا\nلم ترو دجلة ظمأة مني ، وقد … جاورتها ، وتركت ذاك لذاكا\nفمتى أروم الغرب نحوك ، ماتحا … غرب الندى ، فأرى الندى وأراكا\nلا تسألني عن تعذر مطلبي … وكسوف آمالي ، جعلت فداكا\nفلقد طلبت الرزق بعدك معوزا ، … ومدحت ، بعد فراقك ، الأفاكا"},{"id":"diwan-buhturi:51","bookId":"diwan-buhturi","type":"poem","seq":51,"chapter":"البحر: طويل","title":"جعلنا فداك ، الدهر ليس بمنفك","page":"","text":"جعلنا فداك ، الدهر ليس بمنفك … من الحادث المشكو ، والنازل المشكي\nوما هذه الأيام إلا منازل ، … فمن منزل رحب ومن منزل ضنك\nوقد هذبتك الحادثات ، وإنما … صفا الذهب الإبريز قبلك بالسبك\nوما أنت بالمهزوز جأشا على الأذى ، … ولا المتفري الجلدتين على الدعك\nعلى أنه قد ضيم في حبسك الهدى ، … وأضحى بك الإسلام في قبضة الشرك\nأما في نبي الله يوسف أسوة … لمثلك ، محبوسا على الجور والإفك\nأقام جميل الصبر في السجن برهة ، … فآل به الصبر الجميل إلى الملك"},{"id":"diwan-buhturi:52","bookId":"diwan-buhturi","type":"poem","seq":52,"chapter":"البحر: خفيف تام","title":"لو يكون الحباء حسب الذي أن","page":"","text":"لو يكون الحباء حسب الذي أن … ت لدينا له محل وأهل\nلحبيت اللجين والدر واليا … قوت حثوا ، وكان ذاك يقل\nوالشريف الظريف يسمح بالعذ … ر إذا قصر الصديق المقل"},{"id":"diwan-buhturi:53","bookId":"diwan-buhturi","type":"poem","seq":53,"chapter":"البحر: خفيف تام","title":"بأبي أنت ، أنت للبر أهل ،","page":"","text":"بأبي أنت ، أنت للبر أهل ، … والمساعي بعد ، وسعيك قبل\nوالنوال القليل يكثر ، إن شا … ء مرجيك ، والكثير يقل\nغير أني رددت برك ، إذ كا … ن ربا منك ، والربا لا يحل\nوإذا ما جزيت شعرا بشعر … يبلغ الحق ، فالدنانير فضل"},{"id":"diwan-buhturi:54","bookId":"diwan-buhturi","type":"poem","seq":54,"chapter":"البحر: كامل تام","title":"قل للسحاب ، إذا حدته الشمأل ،","page":"","text":"قل للسحاب ، إذا حدته الشمأل ، … وسرى بليل ركبه المتحمل\nعرج على حلب ، فحي محلة … مأنوسة فيها لعلوة منزل\nلغريرة ، أدنو وتبعد في الهوى ، … وأجود بالود المصون ، وتبخل\nوعليلة الألحاظ ، ناعمة الصبى ، … غري الوشاة بها ، ولج العذل\nلا تكذبن ، فأنت ألطف في الحشا … عهدا ، وأحسن في الضمير وأجمل\nلو شئت عدت إلى التناصب في الهوى ، … وبذلت من مكنونه ما أبذل\nأحنو إليك ، وفي فؤادي لوعة ، … وأصد عنك ، ووجه ودي مقبل\nوإذا هممت بوصل غيرك ردني … وله إليك ، وشافع لك أول\nوأعز ثم أذل ذلة عاشق ، … والحب فيه تعزر وتذلل\nإن الرعية لم تزل في سيرة … عمرية ، مذ ساسها المتوكل\nألله آثر بالخلافة جعفرا ، … ورآه ناصرها الذي لا يخذل\nهي أفضل الرتب ، التي جعلت له … دون البرية ، وهو منها افضل\nملك ، إذا عاذ المسىء بعفوه ، … غفر الإساءة ، قادرا لا يعجل\nوعفا كما صفح السحاب ، ورعده … قصف ، وبارقه حريق مشعل\nيتقبل العباس عم محمد ، … ووصيه ، فيما يقول ويفعل\nشرف خصصت به ، ومجد باذخ ، … متمكن فوق النجوم ، مؤثل\nلا يعدمنك المسلمون ، فإنهم … في ظل ملك ادركوا ما أملوا\nحصنت بيضتهم ، وحطت حريمهم ، … وحملت من أعبائهم ما استثقلوا\nفاديت بالأسرى ، وقد غلقوا ، فلا … من ينال ، ولا فداء يقبل\nورأيت وفد الروم ، بعد عنادهم ، … عرفوا فضائلك ، التي لا تجهل\nلحظوك أول لحظة ، فاستصغروا … من كان يعظم فيهم ، ويبجل\nأحضرتهم حجاجا لو اجتلبت بها … عصم الجبال ، لأقبلت تتنزل\nورأوك وضاح الجبين ، كما يرى … قمر السماء السعد ، ليلة يكمل\nنظروا إليك ، فقد سوا ، ولو انهم … نطقوا الفصيح لكبروا ولهللوا\nحضروا السماط فكلما راموا القرى … مالت بأيديهم عقول ذهل\nتهوي أكفهم إلى أفواههم ، … فتحيد عن قصد السبيل ، وتعدل\nمتحيرون ، فباهت متعجب ، … مما رأى ، أو ناظر متأمل\nويود قومهم الأولى بعثوا بهم … لو ضمهم بالأمس ذاك المحفل\nقد نافس الغيب الحضور على الذي … شهدوا ، وقد حسد الرسول المرسل\nفالله أسأل أن تعمر صالحا ، … فدوام عمرك خير شيء يسأل"},{"id":"diwan-buhturi:55","bookId":"diwan-buhturi","type":"poem","seq":55,"chapter":"البحر: كامل تام","title":"لولا تعنفني لقلت : المنزل ،","page":"","text":"لولا تعنفني لقلت : المنزل ، … معنى تبينه ، ومعنى مشكل\nوبوقفة يشفي غليل صبابة ، … ويقول صب ما أراد ويفعل\nسارت مقدمة الدموع ، وخلفت … حرقا توقد في الحشا ، ما ترحل\nإن الفراق ، كما علمت ، فخلني … ومدامعا تسع الفراق ، وتفضل\nإلا يكن صبر جميل ، فالهوى … نشوان يجمل فيه ما لا يجمل\nيا دار ! لا زالت رباك مجودة ، … من كل غادية ، تعل وتنهل\nفهمتنا دول الزمان وصرفه ، … وأريتنا كيف الخطوب النزل\nأصبابة برسوم رامة . بعدما … عرفت معالمها الصبا والشمأل\nوسألت من لا يستجيب فكنت في است … تخباره كمجيب من لا يسأل\nأليوم أطلع للخلافة سعدها ، … وأضاء فيه بدرها المتهلل\nلبست جلالة جعفر ، فكأنها … سحر يجلله النهار المقبل\nجاءته طائعة ، ولم يهزز لها … رمح ، ولم يشهر عليها منصل\nأنى ، وقد كان التلفت نحوه ، … من قبل أن يقع القضاء ، فتعقل\nحتى أتته يقودها استحقاقه ، … ويسوقها حظ إليه مقبل\nعن بيعة ، إلا تكن عقبية ، … فهي التي رضي الكتاب المنزل\nلم تنصرف عنها النفوس ولم تزغ … فيها القلوب ، ولم تزل الأرجل\nمسحوا أكفهم بكف خليفة ، … نجمت بدولته الحقوق الأفل\nوكفتهم الشورى شواهد أعربت … عن أمره ، وفضيلة ما تشكل\nأوما ترى حسن الزمان ، وما بدا ، … وأعاد في أيامه المتوكل\nأشرقن حتى كاد يقتبس الدجى ، … ورطبن حتى كاد يجري الجندل\nمن بعد ما اسود النهار المنتضى … فينا ، وجف لنا الثرى المتبلل\nألله سهل بالخليفة جعفر ، … من دهرنا ، ما لم يكن يتسهل\nملك أذل المعتدين بوطأة ، … ترسو على كبد النفاق ، وتثقل\nإن كل صرف الدهر لم يكلل ، وإن … غفل الربيع ، فجوده لا يغفل\nنفس مشيعة ، ورأي محصد ، … ويد مؤيدة ، وقول فيصل\nوله ، وإن غدت البلاد عريضة ، … طرف بأطراف البلاد موكل\nإسلم أمير المؤمنين لسنة … أحييتها ، والناس حيرى ضلل\nورعية أحسنت رعي سوامها ، … حتى غدت والعدل فيها يهمل\nألله يشكر منك سعيا صادقا … في حفظها ، ثم النبي المرسل\nألفيت عاشقهم ، فإن ندبوا إلى … كرم وإحسان ، فأنت الأول\nوغدوت في برد النبي وهديه … تخشى لحكم قاصد ، وتؤمل"},{"id":"diwan-buhturi:56","bookId":"diwan-buhturi","type":"poem","seq":56,"chapter":"البحر: طويل","title":"تزاجر هذا الناس عني ، تقية ،","page":"","text":"تزاجر هذا الناس عني ، تقية ، … فما بال هذا الطاهري وبالي\nيساجلني ، حتى كأن ليس بحتر … أبي ، وابن همام بن مرة خالي\nأخي وابن عمي سابقتني خصاله … إلى شرف ، أو سابقته خصالي\nبنو الحارث الحراب ، يغشون نصره … بكل جهير في السلاح طوال\nأولئك قوم أنت كفؤ سراتهم ، … وشرواهم في سؤدد ومعال\nلهم ورق الزيتون غضا وعندكم … شريجان من أثل يرف وضال\nتراك مسامي الغداة ، ففائتي … بجملة شعري ، وهو جملة مالي"},{"id":"diwan-buhturi:57","bookId":"diwan-buhturi","type":"poem","seq":57,"chapter":"البحر: طويل","title":"أبى الليل ، إلا أن يعود بطوله","page":"","text":"أبى الليل ، إلا أن يعود بطوله … على عاشق نزر المنام قليله\nلعل اقتراب الدار يثني دموعه ، … فيقلع ، أو يشفى جوى من غليله\nوما زال توحيد المهاري ، وطيها … بنا البعد من حزن الفلا وسهوله\nإلى أن بدا صحن العراق ، وكشفت … سجوف الدجى عن مائه ونخيله\nتظل الحمام الورق ، في جنباته ، … تذكرنا أحبابنا بهديله\nفأحيت محبا رؤية من حبيبه ، … وسرت خليلا أوبة من خليله\nبنعمى أمير المؤمنين وفضله ، … غدا العيش غضا بعد طول ذبوله\nإمام ، يراه الله أولى عباده … بحق ، وأهداهم لقصد سبيله\nخليفته في أرضه ، ووليه ال … رضي لديه ، وابن عم رسوله\nوبحر يمد الراغبون عيونهم … إلى ظاهر المعروف فيهم ، جزيله\nترى الأرض تسقى غيثها بمروره … عليها ، وتكسى نبتها بنزوله\nأتى من بلاد الغرب في عدد النقا ، … نقا الرمل ، من فرسانه وخيوله\nفأسفر وجه الشرق ، حتى كأنما … تبلج فيه البدر بعد أفوله\nوقد لبست بغداد أحسن زيها … لإقباله ، واستشرفت لعدوله\nويثنيه عنها شوقه ونزاعه ، … إلى عرض صحن الجعفري وطوله\nإلى منزل ، فيه أحباؤه الأولى … لقاؤهم أقصى مناه ، وسوله\nمحل يطيب العيش رقة ليله … وبرد ضحاه ، واعتدال أصيله\nلعمري ، لقد آب الخليفة جعفر ، … وفي كل نفس حاجة من قفوله\nدعاه الهوى في سر من راء فانكفا … إليها ، انكفاء الليث تلقاء غيله\nعلى أنها قد كان بدل طيبها ، … ورحل عنها أنسها برحيله\nوإفراطها في القبح ، عند خروجه ، … كإفراطها في الحسن ، عند دخوله\nليهن ابنه ، خير البنين ، محمدا ، … قدوم أب عالي المحل ، جليله\nغدا ، وهو فرد في الفضائل كلها ، … فهل مخبر عن مثله ، أو عديله\nوإن ولاة العهد في الحلم والتقى ، … وفي الفضل من أمثاله وشكوله"},{"id":"diwan-buhturi:58","bookId":"diwan-buhturi","type":"poem","seq":58,"chapter":"البحر: وافر تام","title":"أبعد مبشر ، وأبي عبيد ،","page":"","text":"أبعد مبشر ، وأبي عبيد ، … ومعيوف المكارم والمعالي\nوبعد أبي أبي العطاف أرجو … وفاء الدهر ، أو عهد الليالي\nشيوخ بني عبيد أسلموني … إلى ربع ، من الأكفاء ، خال\nورثت سيوفهم : ومضوا كراما ، … وما نفع السيوف بلا رجال"},{"id":"diwan-buhturi:59","bookId":"diwan-buhturi","type":"poem","seq":59,"chapter":"البحر: وافر تام","title":"رأيت البحبحاني استقلت","page":"","text":"رأيت البحبحاني استقلت … ركائبه بحرمان عظيم\nإذا رام التخلق جاذبته … خلائقه إلى الطبع القديم\nبكى آماله لما رآها … عيانا ، وهي دارسة الرسوم\nوترت القوم ثم ظننت فيهم … ظنونا لست فيها بالحكيم\nتعربد غير محتشم ، وتشدو … فلا تأتي بلحن مستقيم\nفتخطىء في الغناء على المغني ، … وتخطىء في الندام على النديم\nنهيتك عن تعرض عرض حر ، … فإن الذم من شأن الذميم\nوقلت : توق محتملا يوري ، … عن الأضغان ، بالحلم الكريم\nفما خرق السفيه ، وإن تعدى ، … بأبلغ فيك من حقد الحليم\nمتى أحرجت ذا كرم ، تخطى … إليك ببعض أخلاق اللئيم"},{"id":"diwan-buhturi:60","bookId":"diwan-buhturi","type":"poem","seq":60,"chapter":"البحر: كامل تام","title":"أمحلتي سلمى ، بكاظمة ، اسلما ،","page":"","text":"أمحلتي سلمى ، بكاظمة ، اسلما ، … وتعلما أن الجوى ما هجتما\nهل ترويان ، من الأحبة ، هائما ، … أو تسعدان ، على الصبابة ، مغرما\nأبكيكما دمعا ، ولو أني على … قدر الجوى أبكي بكيتكما دما\nأين الغزال المستعير من النقا … كفلا ، ومن نور الأقاحي مبسما\nظمئت جوانحنا إليه ، وريها … في ذلك اللعس الممنع واللمى\nمتعتب في حيث لا متعتب ، … إن لم يجد جرما لدي تجرما\nألف الصدود ، فلو يمر خياله … بالصب في سنة الكرى ، ما سلما\nخلفت بعدهم ألاحظ نية … قذفا ، وأنشد دارسا مترسما\nطللا أكفكف فيه دمعا معربا … بجوى ، وأقرأ فيه خطا أعجما\nتأبى رباه أن تجيب ، ولم يكن … مستخبر ليجيب حتى يفهما\nألله جار بني المدبر ، كلما … ذكرالأكارم ما أعف ، وأكرما\nأخوان في نسب الإخاء لعلة ، … بكرا ، وراحا في السماحة توأما\nيستمطر العافون ، من نوأيهما ، … الشعري العبور غزارة ، والمزرما\nغيثان ، أصبحت العراق لواحد … وطنا ، وغرب واحد ، فتشأما\nولو أن نجدة ذاك ، أو هذا … أمم ، لأدرك طالب ما يمما\nقد كان آن لمغمد أن ينتضى … في حادث ، ولغائب أن يقدما\nإني وجدت لأحمد بن محمد … خلقا ، إذا خنس الجبان ، تقدما\nمتقلقل العزمات في طلب العلى ، … حتى يكون ، على المكارم ، قيما\nالمستضاء بوجهه وبرأيه ، … إن حيرة وقعت وخطب أظلما\nألقى ذراعيه ، وأوقد لحظه … بدمشق ، يعتد النوائب أنعما\nمستصغر للخطب يجمع حزمه … لملمة ، حتى يرى مستعظما\nتقع الأمور بجانبيه ، وإنما … يبعثن رضوى أو يرمن يرمرما\nكلف بجمع الخرج ، يصبح لبه … متفرقا في إثره ، متقسما\nشغل المدافع عن محالة كيده ، … وأذل جبار البلاد الأعظما\nبخعوا بحق الله في أعناقهم ، … لما أتاح لهم قضاء مبرما\nلم يغب عن شيء فيطلبه ، ولم … يجز الذي حد الكتاب ، فيظلما\nأبلغ أبا إسحاق تبلغ لاغبا … في المكرمات معذلا وملوما\nبأبي طلاقتك التي أجلو بها … نظري إذا الغيم الجهام تجهما\nوقديم ما بيني وبينك ، إنه … عقد ، أمر على الزمان ، فأحكما\nكنت الربيع ، فلا العطاء مصردا … فيما يليك ، ولا الإخاء مذمما\nفالدهر تلقاني لسيبك شاكرا ، … إذ كنت لا ألقاك إلا منعما\nقد طال بي عهد وهز جوانحي … شوق ، فجئت من الشآم مسلما"},{"id":"diwan-buhturi:61","bookId":"diwan-buhturi","type":"poem","seq":61,"chapter":"البحر: كامل تام","title":"قل للجنوب : إذا غدوت فبلغي","page":"","text":"قل للجنوب : إذا غدوت فبلغي … كبدي نسيما من جناب نسيم\nأخدعت عنك ، وأنت بدر خادع … لليل عن ظلم له ، وغيوم\nكرم الزمان ولمت فيك ولن ترى … عجبا سوى كرم الزمان ، ولومي\nوظلمت نفسي جاهدا في نفسها ، … فاسمع ندامة ظالم مظلوم\nقد زاد يوم البؤس بعدك ، إنه … أفضى إلي بعقب يوم نعيم\nوأقمت في قلبي ، وشخصك سائر ، … لا تبعدن من سائر ومقيم\nلا كان وجدي أين كان ، وانت لي … ملك وعهدي منك غير ذميم\nالآن أطمع في الوصال ، وبيننا … عين الرقيب ، وباب إبراهيم ؟"},{"id":"diwan-buhturi:62","bookId":"diwan-buhturi","type":"poem","seq":62,"chapter":"البحر: طويل","title":"بني مخلد كفوا تدفق جودكم ،","page":"","text":"بني مخلد كفوا تدفق جودكم ، … ولا تبخسونا حظنا في المكارم\nولا تنصروا مجدي قنان ومالك ، … بأن تذهبوا منا بسمعة حاتم"},{"id":"diwan-buhturi:63","bookId":"diwan-buhturi","type":"poem","seq":63,"chapter":"البحر: طويل","title":"إذا شئت فاندبني إلى الراح ، وانعني","page":"","text":"إذا شئت فاندبني إلى الراح ، وانعني … إلى الشرب من ذي خلة ونديم\nأميلوا الزجاج الصفو عني ، فإنني … أقمت ، وما شخصي لكم بمقيم\nبجسمي سقام ، كلما جزت ردني … إلى كمد ، في الصدر ، غير سقيم\nفإن مت كان الموت من كرم الهوى ، … وليس الهوى ، إن لم أمت بكريم\nفقل لنسيم الورد : عنك ، فإنني … أعاديك إجلالا لوجه نسيم\nندمت ، وقال الناس كيف تركته ؟ … فقل في ملام واقع بمليم\nأبا الفضل ! راجع من حجاك ، فإنني … على خطر ، مما يخاف عظيم\nوخبرتني أن العزاء ، تكرم ، … وهل يتعزى عنه غير لئيم\nفما الدار فيما بيننا ببعيدة ، … ولا العهد فيما بيننا بقديم"},{"id":"diwan-buhturi:64","bookId":"diwan-buhturi","type":"poem","seq":64,"chapter":"البحر: متقارب تام","title":"جاد الذفافي ، في أرضه ،","page":"","text":"جاد الذفافي ، في أرضه ، … ركام الغمام على ظلمه\nأخ لي لم تتصل نسبتي … بقربى أبيه ، ولا أمه\nتبدل ، حتى لأنكرته ، … سوى أنني عارف باسمه\nوما لي منه سوى رقة ، … يراح لها الشعر من فهمه\nكذا المسك ما فيه مستمتع … لمتخذيه ، سوى شمه"},{"id":"diwan-buhturi:65","bookId":"diwan-buhturi","type":"poem","seq":65,"chapter":"البحر: خفيف تام","title":"قد فقدنا الوفاء فقد الحميم ،","page":"","text":"قد فقدنا الوفاء فقد الحميم ، … وبكينا العلى بكاء الرسوم\nلا أمل الزمان ذما ، وحسبي … شغلا أن ذممت كل ذميم\nأتظن الغنى ثوابا لذي الهمة … من وقفة بباب لئيم\nوأرى عند خجلة الرد مني … خطرا في السؤال ، جد عظيم\nولوجه البخيل أحسن في بع … ض الأحايين من قفا المحروم\nوكريم عدا ، فأعلق كفي ، … مستميحا في نعمة من كريم\nحاز حمدي ، وللرياح اللواتي … تجلب الغيث ، مثل حمد الغيوم\nعودة بعد بدأة منك كانت … أمس ، يا أحمد بن عبد الرحيم\nما تأنيك بالظنين ولا وج … هك في وجه حاجتي بشتيم"},{"id":"diwan-buhturi:66","bookId":"diwan-buhturi","type":"poem","seq":66,"chapter":"البحر: خفيف تام","title":"إن طيفا يزورني في المنام ،","page":"","text":"إن طيفا يزورني في المنام ، … لخلي من لوعتي ، وغرام\nغادة بت أحمل اللوم فيها ، … وعناء المحب طو الملام\nنظرت خلسة إلي ، فأعدى … بدني طرف عينها بالسقام\nأنثت ثم ذكرت فلها دل … فتاة رود ، وقد غلام\nولحسن الحلال فضل ، إذا ما … شابه في القلوب ظرف الحرام\nقد سقتني ، بكأسها وبفيها ، … ما يروي من غلة المستهام\nفي اعتدال من الزمان يباري … ها فتحكيه باعتدال القوام\nإنما العيش أن تكون الليالي … مفضلات ، طولا ، على الأيام\nقد صفا جانب الهواء ، ولذت … رقة الماء في مزاج المدام\nواستتم الصحيح في خير وقت ، … فهو مغنى أنس ، ودار مقام\nناظر وجهة المليح فلو يس … طيع حياه معلنا بالسلام\nألبسا بهجة ، وقابل ذا ذاك … فمن ضاحك ومن بسام\nكالمحبين ، لو أطاقا التقاء ، … أفرطا في العناق والإلتزام\nتنفذ الريح جريها بين قطري … ه، فتكبو من ونية وسآم\nمستمد بجدول من عباب الس … ماء كالأبيض الصقيل الحسام\nوإذا ما توسط البركة الحس … ناء ألقت عليه صبغ الرخام\nفتراه كأنه ماء بحر ، … يخدع العين ، وهو ماء غمام\nوالدواليب ، إن يدرن ، ولا نا … ضح يمشي بهن غير النعام\nبدع أنشئت لأولى عباد الله … بالركن ، الصفا ، والمقام\nإن خير القصور أصبح مزهوا … بكره العدى لخير الأنام\nجاور الجعفري ، وانحاز شبدا … زإليه كالراغب المعتام\nحلل من منازل الملك كالأن … جم ، يلمعن في سواد الظلام\nمفحمات تعيي الصفات فما تد … رك إلا بالظن والأوهام\nفكأنا نحسها في الأماني ، … أو نراها في طارق الأحلام\nغرف من بناء دين ودنيا ، … يوجب الله فيه أجر الإمام\nشوقتنا إلى الجنان فزدنا … في اجتناب الذنوب والآثام\nوبها تشرب الأوائل ملكا ، … وتباهي مكاثري الإسلام\nبارك الله للخليفة في المج … د المعلى ، والمأثرات العظام\nوأراه آماله في ولاة ال … عهد أهل الوفاء والإنعام\nلا يزالوا بغبطة وسرور ، … وبقاء ، من ملكه ، ودوام"},{"id":"diwan-buhturi:67","bookId":"diwan-buhturi","type":"poem","seq":67,"chapter":"البحر: بسيط تام","title":"أعن جوار أبي إسحاق تطمع أن","page":"","text":"أعن جوار أبي إسحاق تطمع أن … تزيل رحلي ، يا بهل بن بهلانا\nغبينة سمتنيها ، لو سمحت بها … يوما ، لأكفلتها لخما وغسانا\nاعتدت من قطرك الأقصى لتقمرني … بني المدبر أنصارا ، وأعوانا\nيرضاهم الناس أربابا لسؤددهم ، … فكيف أسخطهم ، يا بهل إخوانا\nهبني غنيت بوفري عن نوالهم ، … فكيف أصنع بالإلف الذي كانا\nعهد من الأنس عاقرنا الكؤوس على … بديئه ، وخبطنا فيه أزمانا\nنماز عنه كهولا ، بعد كبرتنا ، … وقد قطعنا به الأيام شبانا\nأصادق لم أكذبهم مودتهم ، … ولم أدعهم لشيء عز أوهانا\nولم أكن بائعا بالرغب عبدهم ، … وأنت تطلبهم ، يا بهل ، مجانا\nإذهب إليك ، فلا محظى بعارفة ، … ولا مصيبا ، لما حاولت ، إمكانا"},{"id":"diwan-buhturi:68","bookId":"diwan-buhturi","type":"poem","seq":68,"chapter":"البحر: متقارب تام","title":"تعاط الصبابة ، أو عانها ،","page":"","text":"تعاط الصبابة ، أو عانها ، … لتعذر في برح أشجانها\nوما نقلت لوعتي لمة ، … تنقل في حدث ألوانها\nأوائل شيب يشير العذول … إليها ، ويكبر من شأنها\nإذا حرم االلهو من أجلها ، … غلا في مقادير أوزانها\nوإلا تجدني مطيعا لها ، … فلم أعصها كل عصيانها\nمتى جئت بائقة في الهوى ، … فأسرارها دون إعلانها\nتعامى رجال عن المكرما … ت ، وقد مثلت نصب أعيانها\nولم تلتفت لوجوب الحقوق ، … وواجبها خلف آذانها\nفتحت يدي ثاني العطف عن … كذوب المودة ، خوانها\nوقد علمت خلتي أنني … أفارقها ، عند هجرانها\nوإني لأسكن جأشا إلى … رباع الكرام ، وأوطانها\nوبعدت نفسي من مالها ، … وما أبعدت مال إخوانها\nرضيت خليلي أبا غالب ، … لكسر الخطوب ، وإيهانها\nتعد له فارس قربة ، … وزلفى بكسرى بن ساسانها\nإذا سئلت عنه عند الفخار ، … قالت بأصدق عرفانها\nيطولون منه بإنسانهم ، … وللعين طول بإنسانها\nهتكنا إليه حجاب الدجى ، … بخوص تباري بركبانها\nتكلفنا لنروم الوداع … مسافة قم وقاسانها\nوسن سميرة طيف الفتاة … تبسم عن ظلم أسنانها\nإذا استشرقت لمعان الثلوج … أطاعت له قبل إبانها\nفهالك أنجز أعوانها … فوق السحاب وأعنانها\nإلى الملك غلقت عنده … رقاب المديح بأثمانها\nوقيت الحمام بمثنى النفوس … من الحاسدين ووحدانها\nتبوخ المعالي ، إذا لم يكن … بكفيك إذكاء نيرانها\nوتجزل في القوم حتى تكون … فعالك أنجز أعوانها\nحمت قضب المجد من أن تكون … صلاء صلابة عيدانها\nوعافت بك الذم نفس جرت … إلى الحمد ، في طول ميدانها\nأخذت العطايا بتكرارها ، … وإبداء طول بثنيانها\nأرى بذلها ، عند إعوازها ، … سوى بذلها عند إمكانها\nوأحسن مأثرة للكرام ، … إحسانها عند إحسانها\nوما يتنمى إلى المكرمات … فيفرعها ، غير فرسانها\nلمن عاد بعدي عن ساحتيك … بنقص حظوظي ، وخسرانها\nوكان اجتنابيك إحدى الذنوب ، … فقصديك أولى بغفرانها\nوما عوقبت عصبة ، أمنت … على كفرها ، بعد إيمانها\nفإن خواتيم أعمال ما … تراه جوامع أديانها"},{"id":"diwan-buhturi:69","bookId":"diwan-buhturi","type":"poem","seq":69,"chapter":"البحر: خفيف تام","title":"ملنا ، أم نبا بنا ، أم جفانا ،","page":"","text":"ملنا ، أم نبا بنا ، أم جفانا ، … أم قلانا ، فاعتاض عنا سوانا\nساخط نبتغي رضاه ولا يس … أل عن سخطنا ، ولا عن رضانا\nونبالي ألا نرى ذا تجن … لا يبالي الزمان ، ألا يرانا\nصيق العذر في الضراعة ، إنا … لو قنعنا بقسمنا لكفانا\nما لنا نعبد العباد إذا كا … ن ، إلى الله ، فقرنا وغنانا"},{"id":"diwan-buhturi:70","bookId":"diwan-buhturi","type":"poem","seq":70,"chapter":"البحر: خفيف تام","title":"إدمع قد أغرين بالهملان ،","page":"","text":"إدمع قد أغرين بالهملان ، … وفؤاد قد لج في الخفقان\nإن يوم الكثيب أفقدنا نض … رة تلك القضبان والكثبان\nبفراق ألم بعد اجتماع ، … وتناء أقام بعد تدان\nإبكيا هذه المغاني التي أخ … لمقها بعد عهدها بالغواني\nأسعد الغيث إذ بكاها وإن كان … خليا من كل ما تجدان\nجاد فيها بنفسه ، فاستجدت … حللا منه ، جمة الألوان\nفهي تهتز بين إفرنده الأخ … ضر ، حسنا ، ووشيه الأرجواني\nفي سماء من خضرة الروض فيها … أنجم من شقائق النعمان\nواصفرار من لونه ، وابيضاض … كاجتماع الحوذان والأقحوان\nصاغ منها الربيع شكلا لأخلا … ق حسين ذي الجود والإحسان\nفكأن الصبا تردد فيها … بنسيم الكافور ، والزعفران\nقد تصابيت ، فاعذري ، أو فلومي ، … ليس شيء من الصبى من شاني\nوتذكرت وافد الشيب فاستع … جلت حظي في الراح والريحان\nعند عدل من الزمان إذا استق … بنثير الياقوت ، والمرجان\nولقد أمزج المدام بفتر ، … بل بسحر من مقلتي أرسلان\nوأعاطي كؤوسها الملك الأب … لخ ، فعل الندمان والندمان\nفكأني أنادم القمر البد … ر عليها ، في ذلك الإيوان\nيزدهيه من العلى كبرياء … فيه ، أن يزدهي على الإخوان\nوعليه من الندى سيمياء ، … وصلت مدحه بكل لسان\nغمرته جلالة الملك ، واستو … لت عليه شمائل الفتيان\nواصل مجده بعقد الثريا ، … ويداه بالجود موصولتان\nيا أبا القاسم المقسم في المج … د ليوم الندى ويوم الطعان\nقد ورثت العلياء عن أزدشير ، … وقباذ ، وعن أنوشروان\nوأرى الليل والنهار سواء ، … حين تبدو بوجهك الإضحيان"},{"id":"diwan-buhturi:71","bookId":"diwan-buhturi","type":"poem","seq":71,"chapter":"البحر: بسيط تام","title":"ليت الخليط الذي قد بان لم يبن","page":"","text":"ليت الخليط الذي قد بان لم يبن … وليت ما كان من حبيك لم يكن\nأحرى العيون بأن تجري مدامعها … عين ، بكت شجوها من منظر حسن\nيا نظرة لي من الشمس التي طلعت … في الرائحين ، بسرب الزبرب القطن\nما أحسن الصبر ، إلا عند فرقة من … ببثه صرت بين البث والحزن\nكثيب رمل على عليائه فنن ، … وشمس دجن بأعلى ذلك الفنن\nما تقع العين منها حين تلحظها ، … إلا على فتنة من أقتل الفتن\nقامت تثنى ، فلانت في مجاسدها ، … حتى كأن قضيب البان لم يلن\nلي عن قليل لا يلم به … وجد عليك ، وقلب غير مرتهن\nإن الهموم ، إذا أوطن في خلد … للمرء ، سار ولم يربع على وطن\nإلى المهذب إبراهيم أوصلنا … آذي دجلة في عير من السفن\nغرائب الريح تحدوها ، ويجنبها … هاد من الماء ، منقاد بلا رسن\nجئناك نحمل ألفاظا مدبجة ، … كأنما وشيها من يمنة اليمن\nكأنها وهي تمشي البخترية في … يدي أبي الفضل أو في نائل الحسن\nنهدي القريض إلى رب القريض معا … كحامل العصب يهديه إلى عدن\nمن كل زهراء ، كالنوار ، مشرقة ، … أبقى على الزمن الباقي من الزمن\nشكر امرىء ظل مشغولا بشكرك عن … فرط البكاء على الأطلال ، والدمن\nقد قلت إذ بسطت كفاك من أملي : … ما شاء من نائبات الدهر ، فليكن\nرضيت منك بأخلاق قد امتزجت … بالمكرمات امتزاج الروح بالبدن\nوزدتني رغبة في عقد ودك ، إذ … شفعت ذاك الندى بالفهم ، والفطن\nمن يصبه سكن ممن يحب ، ومن … يهوى ، فما لك غير الجود من سكن\nبدني إلى الجود كفا منك قد أنست … بالبذل والعرف أنس العين بالوسن"},{"id":"diwan-buhturi:72","bookId":"diwan-buhturi","type":"poem","seq":72,"chapter":"البحر: خفيف تام","title":"أرق العين أن قرة عيني","page":"","text":"أرق العين أن قرة عيني … دخلت بينه الليالي ، وبيني\nإن يقدر لنا الزمان التقاء ، … فهو حكمي على الزمان ، وديني\nما لشيء بشاشة ، يعد شيء ، … كتلاق مواشك ، بعد بين"},{"id":"diwan-buhturi:73","bookId":"diwan-buhturi","type":"poem","seq":73,"chapter":"البحر: منسرح","title":"قل لأبي جعفر ، فإن له","page":"","text":"قل لأبي جعفر ، فإن له … يدا ينال البعيد نائلها\nتأبى يد الغيث أن تساجلها ، … ويقصر الدهر أن يطاولها\nبقيت في قاسط ، فحينئذ … تبقى ربى المجد والعلاء لها\nمنعت بالمرهفات جارمها ، … وعلت بالمكرمات عائلها\nتعد أفعالك الحصينة ، إن … قبيلة عددت معاقلها\nكم لك فيها من نائل ويد ، … سدت به بكرها ووائلها\nأذيع جدواك أمأكون كمن … يكتم شؤبوبها ووابلها\nها إنها نعمة ، إذا ذكرت ، … كانت عطاء ، وكنت باذلها\nلن يتولى إتمام آخرها ، … إلا كريم أنشا أوائلها\nكنت ببدء الإحسان عاجلها ، … فكن بعود الإحسان آجلها"},{"id":"diwan-buhturi:74","bookId":"diwan-buhturi","type":"poem","seq":74,"chapter":"البحر: متقارب تام","title":"هجاني النغيل ، وما خلتني","page":"","text":"هجاني النغيل ، وما خلتني … أخاف هجاء أبي حرمله\nوقد كنت أطنب في وصفه ، … وتشبيت نسبته المشكله\nأرجي تلونه بالصفا ، … وألقى قطيعته بالصله\nأراه وفيا ، وأنى له … وفاء ، إذا كان لا أصل له\nفلا تحمدان من أخ آخر … إذا أنت لم تختبر أوله\nفإن يك أخلف ظني به ، … وحال عن العهد أو بدله\nفما كنت أول من فاته ، … لدى صاحب ، بعض ما أمله\nألم أختصصك بما قد علم … ت من الود ، والمقة المكمله\nوأسأل فيك أبا صالح ، … وما كان حقك أن أسأله\nأخبر أنك مستوجب … للطف المحلة ، والمنزله\nوكان جزائي ما قد علم … ت وما لم يكن لك أن تفعله\nأراك رجعت إلى جدك ال … شريف ، وقصتك المعضله\nومسراه في بطن قوصره ، … مخرقة الخوص ، مستعمله\nإذا اسود من خلف تشبيكها ، … توهمته الطن في الدوخله\nفلله هيئته مصبحا ، … وقد وجدوه على المزبله\nيعبي الذباب كراديسه ، … فتغشاه قنبلة قنبله\nهنالك لو تدعيه قشير … لما خيلت أنها مبطله"},{"id":"diwan-buhturi:75","bookId":"diwan-buhturi","type":"poem","seq":75,"chapter":"البحر: متقارب تام","title":"أبا جعفر ! ليس فضل الفتى","page":"","text":"أبا جعفر ! ليس فضل الفتى … إذا راح في فرط إعجابه\nولا في فراهة برذونه ، … ولا في نظافة أثوابه\nولكنه في الفعال الكريم … والخطر الأشرف النابه\nرأيتك تهوى اقتناء المديح … وتجهل مقدار إيجابه\nوكيف ترجي وصولا إليه … ولم تتوصل بأسبابه\nوإن أتطلب به نائلا ، … فلست مليئا بإطلابه\nوإن أتصدق به حسبة ، … فإن المساكين أولى به"},{"id":"diwan-buhturi:76","bookId":"diwan-buhturi","type":"poem","seq":76,"chapter":"البحر: خفيف تام","title":"قصة التل ، فاسمعوها عجابه ،","page":"","text":"قصة التل ، فاسمعوها عجابه ، … إن في مثلها تطول الخطابه\nلإدعى التل فرقتان تلاحوا : … آل عبد الأعلى ، وآل ثوابه\nحكم العادل الجنيدي فيهم … بصواب ، فلا عدمنا صوابه\nإحفروا التل يا بني عبد الأع … لى ، وأثيروا صخوره وترابه\nإن وجدتم فيه شباك أبيكم ، … كنتم دون غيركم أربابه\nأو وجدتم محاجما ، إن حفرتم ، … زال شك العصابة المرتابه\nفبدت جونة من الخوص فيها … آلة الشيخ ، وهو جد لبابه"},{"id":"diwan-buhturi:77","bookId":"diwan-buhturi","type":"poem","seq":77,"chapter":"قصائد","title":"ألا لله درك ، يا جللتا ،","page":"","text":"ألا لله درك ، يا جللتا ، … وما أخرجت من أهل الكتابه\nنقلت عن المشارط والمواسي … إلى الأقلام ، حال بني ثوابه"},{"id":"diwan-buhturi:78","bookId":"diwan-buhturi","type":"poem","seq":78,"chapter":"قصائد","title":"إن الزمان سو ،","page":"","text":"إن الزمان سو ، … وجميع هذا الخلق بو\nفإذا سألتهم ندى ، … فجوابهم عن ذاك وو\nلو يمكلون الضوء بخ … لا لم يكن للخلق ضو\nذهب الكرام بأسرهم ، … وبقي لنا ليت ولو"},{"id":"diwan-buhturi:79","bookId":"diwan-buhturi","type":"poem","seq":79,"chapter":"قصائد","title":"لنا أبدا يث نعانيه في أروى ،","page":"","text":"لنا أبدا يث نعانيه في أروى ، … وحزوى ، وكم أدنتك من لوعة حزوى\nوما كان دمعي قبل أروى بنهزة … لأدنى خليط بان أو منزل أقوى\nإذا ارتاح للإحسان ، أيهما أضوى … تعلقها قلب مريض ، بها يدوى\nوأكثرت من شكوى هواها ، وإنما … أمارة برح الحب أن تكثر الشكوى"},{"id":"diwan-buhturi:80","bookId":"diwan-buhturi","type":"poem","seq":80,"chapter":"البحر: خفيف تام","title":"باكرتنا بواكر الوسمي ،","page":"","text":"باكرتنا بواكر الوسمي ، … ثم راحت ، وأقبلت بالولي\nوأرى الغيث ليس ينفك يهمي … في غداة مخضلة ، وعشي\nفسقى الأرض ريها من نداه ، … فاسقني ، من سلافة الراح ، ريي\nأصبحت بهجة النعيم ، وأمست … بين قصر الصبيح والجعفري\nفي البناء العجيب ، والمنزل الآ … نس ، والمنظر الجميل ، والبهي\nورياض تصبو النفوس إليها ، … وتحيا بنورهن الجني\nدار ملك مختارة لإمام ، … أحرزت كفه تراث النبي\nوهب الله للرعية منه … سيرة الفاضل ، التقي ، الذكي\nفهي محبوة بإحسانه الضا … في عليها ، وحكمة المرتضي\nيا إمام الهدى ، ويا صاحب الحق ، … ويا ابن الرشيد ، والمهدي\nليدم دهرك المحبب في النا … س بعمر باق ، عيش رضي"}]};